window.LCE_GLOSSA = Object.assign(window.LCE_GLOSSA || {}, {
  "1Cor 1,1-3": "PAULO CHAMADO APÓSTOLO / À IGREJA DE DEUS EM CORINTO / SANTIFICADOS EM CRISTO.\nGRAÇA E PAZ / DEUS PAI E JESUS CRISTO.",
  "1Cor 1,10-13.17": "PAULO PEDIR IRMÃOS: DIVISÕES NÃO / MESMO PENSAMENTO E PROPÓSITO.\nGRUPOS DIZER EU DE PAULO / APOLO / PEDRO / CRISTO.\nCRISTO ESTÁ DIVIDIDO? PAULO FOI CRUCIFICADO POR VOCÊS?\nCRISTO ME ENVIOU PRINCIPALMENTE ANUNCIAR EVANGELHO / NÃO SABEDORIA DE PALAVRAS QUE ESVAZIE CRUZ.",
  "1Cor 1,22-25": "JUDEUS PEDIR SINAIS / GREGOS BUSCAR SABEDORIA.\nNÓS ANUNCIAR CRISTO CRUCIFICADO / ESCÂNDALO PARA UNS / LOUCURA PARA OUTROS.\nPARA CHAMADOS / CRISTO PODER E SABEDORIA DE DEUS.\nLOUCURA DE DEUS MAIS SÁBIA QUE HUMANOS / FRAQUEZA DE DEUS MAIS FORTE.",
  "1Cor 1,26-31": "IRMÃOS / OLHAR CHAMADO DE VOCÊS: POUCOS SÁBIOS / PODEROSOS / NOBRES SEGUNDO MUNDO.\nDEUS ESCOLHER O QUE MUNDO CONSIDERA FRACO E PEQUENO / CONFUNDIR FORTE E IMPORTANTE.\nNINGUÉM SE GLORIAR DIANTE DEUS.\nCRISTO PARA NÓS SABEDORIA / JUSTIÇA / SANTIFICAÇÃO / REDENÇÃO.\nQUEM SE GLORIAR / GLORIAR NO SENHOR.",
  "1Cor 1,3-9": "GRAÇA E PAZ A VOCÊS.\nEU AGRADECER DEUS PELA GRAÇA DADA EM CRISTO.\nVOCÊS ENRIQUECIDOS EM PALAVRA E CONHECIMENTO / NENHUM DOM FALTAR ENQUANTO ESPERAM JESUS.\nDEUS FORTALECER ATÉ FIM / ELE FIEL / CHAMOU VOCÊS À COMUNHÃO COM FILHO.",
  "1Cor 10,1-6.10-12": "PAULO LEMBRAR ISRAEL: TODOS SOB NUVEM / PASSAR MAR / RECEBER MESMOS SINAIS / MAS MUITOS NÃO AGRADARAM DEUS.\nESSAS COISAS SERVEM EXEMPLO PARA NÓS / NÃO DESEJAR MAL / NÃO MURMURAR.\nQUEM PENSA ESTAR FIRME / CUIDADO PARA NÃO CAIR.",
  "1Cor 10,31–11,1": "COMER / BEBER / QUALQUER COISA / FAZER TUDO PARA GLÓRIA DEUS.\nNÃO SER CAUSA TROPEÇO JUDEUS / GREGOS / IGREJA.\nBUSCAR BEM DE MUITOS / PARA SALVAÇÃO.\nIMITAR-ME COMO EU IMITO CRISTO.",
  "1Cor 12,12-30": "CORPO É UM / TEM MUITOS MEMBROS / ASSIM CRISTO.\nTODOS BATIZADOS NUM SÓ ESPÍRITO / UM CORPO.\nPÉ NÃO PODE DIZER NÃO SOU MÃO / OLHO NÃO PODE DIZER NÃO PRECISO DE VOCÊ.\nDEUS ORGANIZOU MEMBROS / OS MAIS FRÁGEIS SÃO NECESSÁRIOS.\nSE UM SOFRE / TODOS SOFREM; SE UM HONRADO / TODOS ALEGRAM.\nVOCÊS SÃO CORPO DE CRISTO / CADA UM MEMBRO.",
  "1Cor 12,3-7.12-13": "NINGUÉM PELO ESPÍRITO DEUS DIZ JESUS MALDITO / E NINGUÉM DIZ JESUS É SENHOR SENÃO ESPÍRITO SANTO.\nDONS DIFERENTES / MESMO ESPÍRITO; SERVIÇOS DIFERENTES / MESMO SENHOR; AÇÕES DIFERENTES / MESMO DEUS.\nA CADA UM MANIFESTAÇÃO ESPÍRITO PARA BEM COMUM.\nUM CORPO / MUITOS MEMBROS / TODOS BATIZADOS NUM ESPÍRITO.",
  "1Cor 12,31–13,13": "BUSCAR DONS MELHORES / MAS EU MOSTRAR CAMINHO SUPERIOR.\nSE FALAR LÍNGUAS / PROFETIZAR / CONHECER / TER FÉ / DAR TUDO / MAS AMOR NÃO / NADA SOU.\nAMOR PACIENTE / BONDOSO / NÃO INVEJAR / NÃO SE EXALTAR / NÃO BUSCAR PRÓPRIO INTERESSE / NÃO GUARDAR RANCOR / ALEGRAR VERDADE / TUDO SUPORTAR E ESPERAR.\nFÉ / ESPERANÇA / AMOR PERMANECEM / MAIOR É AMOR.",
  "1Cor 12,4-11": "DONS DIFERENTES / MESMO ESPÍRITO.\nSERVIÇOS DIFERENTES / MESMO SENHOR.\nAÇÕES DIFERENTES / MESMO DEUS.\nA CADA PESSOA ESPÍRITO SE MANIFESTAR PARA BEM COMUM: SABEDORIA / CONHECIMENTO / FÉ / CURA / MILAGRES / PROFECIA / DISCERNIMENTO / LÍNGUAS.\nUM MESMO ESPÍRITO DISTRIBUI COMO QUER.",
  "1Cor 15,1-11": "PAULO LEMBRAR EVANGELHO RECEBIDO / NO QUAL VOCÊS PERMANECEM.\nCRISTO MORREU POR NOSSOS PECADOS / FOI SEPULTADO / RESSUSCITOU TERCEIRO DIA / APARECEU A PEDRO / DOZE / MUITOS / DEPOIS A PAULO.\nPAULO SE CONSIDERA MENOR / MAS GRAÇA DEUS NELE NÃO FOI VAZIA.\nSEJA EU OU ELES / ISSO PREGAMOS / ISSO VOCÊS CRERAM.",
  "1Cor 15,12.16-20": "SE PREGAMOS CRISTO RESSUSCITOU / COMO ALGUNS DIZEM NÃO EXISTE RESSURREIÇÃO?\nSE MORTOS NÃO RESSUSCITAM / CRISTO TAMBÉM NÃO / FÉ VAZIA / PECADOS PERMANECEM.\nMAS CRISTO DE FATO RESSUSCITOU / PRIMEIRO FRUTO DOS QUE MORRERAM.",
  "1Cor 15,20-26.28": "CRISTO RESSUSCITOU / PRIMEIRO FRUTO DOS MORTOS.\nPOR UM HOMEM VEIO MORTE / POR UM HOMEM VEM RESSURREIÇÃO.\nEM ADÃO TODOS MORREM / EM CRISTO TODOS RECEBERÃO VIDA.\nCRISTO REINAR ATÉ COLOCAR INIMIGOS SOB PÉS / ÚLTIMO INIMIGO DESTRUIR: MORTE.\nNO FIM FILHO ENTREGAR TUDO AO PAI / DEUS SER TUDO EM TODOS.",
  "1Cor 15,45-49": "PRIMEIRO HOMEM ADÃO / SER VIVO TERRENO.\nÚLTIMO ADÃO / CRISTO / ESPÍRITO QUE DÁ VIDA.\nPRIMEIRO VEM CORPO NATURAL / DEPOIS ESPIRITUAL.\nCOMO TROUXEMOS IMAGEM HOMEM TERRENO / TRAREMOS IMAGEM HOMEM CELESTE.",
  "1Cor 15,54-58": "QUANDO CORRUPTÍVEL VESTIR INCORRUPTÍVEL / MORTE SERÁ ENGOLIDA NA VITÓRIA.\nMORTE / ONDE TUA VITÓRIA? ONDE TEU AGUILHÃO?\nDEUS NOS DÁ VITÓRIA POR JESUS CRISTO.\nPORTANTO IRMÃOS / FIRMES / CONSTANTES / TRABALHAR SENHOR / SABER ESFORÇO NÃO É VAZIO.",
  "1Cor 2,1-5": "PAULO: QUANDO CHEGUEI / NÃO VIM COM DISCURSO IMPRESSIONANTE.\nDECIDI CONHECER ENTRE VOCÊS JESUS CRISTO / E CRUCIFICADO.\nEU ESTAVA FRACO / TEMOR / TREMORES.\nMINHA PALAVRA NÃO APOIAR SABEDORIA HUMANA / MAS DEMONSTRAÇÃO ESPÍRITO E PODER.\nFÉ DE VOCÊS BASEAR PODER DEUS.",
  "1Cor 2,6-10": "ENTRE MADUROS / FALAMOS SABEDORIA / NÃO DESTE MUNDO.\nSABEDORIA DEUS ESCONDIDA / PREPARADA PARA NOSSA GLÓRIA.\nPODEROSOS NÃO ENTENDERAM / SENÃO NÃO CRUCIFICARIAM SENHOR GLÓRIA.\nO QUE OLHO NÃO VIU / OUVIDO NÃO OUVIU / DEUS PREPAROU PARA QUEM AMA.\nDEUS REVELOU PELO ESPÍRITO.",
  "1Cor 3,16-23": "VOCÊS NÃO SABEM? VOCÊS SÃO TEMPLO DE DEUS / ESPÍRITO HABITA EM VOCÊS.\nTEMPLO DEUS SANTO / VOCÊS ESSE TEMPLO.\nNINGUÉM SE ENGANE COM SABEDORIA DESTE MUNDO.\nNÃO SE GLORIAR EM PESSOAS.\nTUDO É DE VOCÊS / VOCÊS DE CRISTO / CRISTO DE DEUS.",
  "1Cor 4,1-5": "CONSIDERAR NÓS SERVIDORES CRISTO / ADMINISTRADORES MISTÉRIOS DEUS.\nADMINISTRADOR PRECISA SER FIEL.\nJULGAMENTO HUMANO NÃO É ÚLTIMA MEDIDA / NEM EU JULGO A MIM MESMO.\nSENHOR É QUEM JULGA.\nNÃO JULGAR ANTES TEMPO / SENHOR REVELAR INTENÇÕES CORAÇÕES / CADA UM RECEBER LOUVOR DE DEUS.",
  "1Cor 6,13-15.17-20": "CORPO NÃO PARA IMORALIDADE / MAS PARA SENHOR / SENHOR PARA CORPO.\nDEUS RESSUSCITOU SENHOR / RESSUSCITARÁ NÓS.\nCORPOS DE VOCÊS SÃO MEMBROS DE CRISTO.\nQUEM SE UNE SENHOR / UM ESPÍRITO COM ELE.\nFUGIR IMORALIDADE.\nCORPO DE VOCÊS TEMPLO ESPÍRITO SANTO / VOCÊS NÃO PERTENCEM A SI MESMOS / FORAM COMPRADOS POR PREÇO / GLORIFICAR DEUS NO CORPO.",
  "1Cor 7,29-31": "IRMÃOS / TEMPO É BREVE.\nRELACIONAMENTOS / ALEGRIAS / TRISTEZAS / BENS / USO DO MUNDO / NÃO TRATAR COMO ABSOLUTOS.\nFORMA DESTE MUNDO PASSA.",
  "1Cor 7,32-35": "PAULO QUER VOCÊS LIVRES DE PREOCUPAÇÃO QUE DIVIDA CORAÇÃO.\nQUEM NÃO CASADO PODE CUIDAR COISAS SENHOR; CASADO TAMBÉM TEM RESPONSABILIDADES CÔNJUGE E CASA.\nNÃO DIGO PARA PRENDER VOCÊS / MAS PARA O QUE É DIGNO / SERVIR SENHOR SEM DISTRAÇÃO.",
  "1Cor 9,16-19.22-23": "ANUNCIAR EVANGELHO / PARA PAULO NÃO É MOTIVO ORGULHO / É NECESSIDADE: AI DE MIM SE NÃO EVANGELIZAR.\nRECOMPENSA: ANUNCIAR GRATUITAMENTE / NÃO USAR DIREITOS.\nSENDO LIVRE / FIZ-ME SERVO DE TODOS / GANHAR MAIS.\nFIZ-ME FRACO COM FRACOS / TUDO PARA TODOS / PARA SALVAR ALGUNS.\nTUDO FAÇO POR CAUSA EVANGELHO.",

  "1Jo 2,1-5": "FILHOS / ESCREVO PARA VOCÊS NÃO PECAR.\nSE ALGUÉM PECAR / TEMOS DEFENSOR JUNTO PAI: JESUS CRISTO JUSTO.\nELE É SACRIFÍCIO PELOS NOSSOS PECADOS / E DO MUNDO.\nSABEMOS QUE CONHECEMOS DEUS SE GUARDAMOS MANDAMENTOS.\nQUEM DIZ CONHEÇO MAS NÃO GUARDA / MENTE.\nQUEM GUARDA PALAVRA / AMOR DEUS SE APERFEIÇOA.",
  "1Jo 3,1-2": "VEJAM QUE AMOR PAI NOS DEU / SER CHAMADOS FILHOS DE DEUS / E SOMOS.\nMUNDO NÃO NOS CONHECE PORQUE NÃO CONHECEU DEUS.\nAGORA SOMOS FILHOS / AINDA NÃO APARECEU O QUE SEREMOS.\nQUANDO ELE SE MANIFESTAR / SEREMOS SEMELHANTES / VEREMOS COMO ELE É.",
  "1Jo 3,1-2.21-24 ou Cl 3,12-21": "OPÇÃO 1 — PAI NOS CHAMAR FILHOS DE DEUS / CONFIANÇA DIANTE DELE / GUARDAR MANDAMENTO: CRER JESUS CRISTO E AMAR UNS AOS OUTROS / ESPÍRITO MOSTRAR QUE ELE PERMANECE EM NÓS.\nOPÇÃO 2 — COMO ESCOLHIDOS DE DEUS / REVESTIR COMPAIXÃO / BONDADE / HUMILDADE / PACIÊNCIA / PERDÃO / AMOR / PAZ; PALAVRA CRISTO HABITAR; VIDA FAMILIAR EM RESPEITO E AMOR.",
  "1Jo 3,18-24": "FILHOS / AMAR NÃO SÓ PALAVRAS / MAS AÇÃO E VERDADE.\nASSIM SABER SOMOS DA VERDADE / CORAÇÃO DESCANSAR DIANTE DEUS.\nSE CORAÇÃO NÃO CONDENA / CONFIANÇA PARA PEDIR.\nMANDAMENTO: CRER NOME JESUS CRISTO / AMAR UNS AOS OUTROS.\nQUEM GUARDA MANDAMENTOS / PERMANECE EM DEUS / DEUS NELE / ESPÍRITO CONFIRMA.",
  "1Jo 4,7-10": "AMADOS / AMAR UNS AOS OUTROS / AMOR VEM DE DEUS.\nQUEM AMA / NASCEU DE DEUS / CONHECE DEUS.\nQUEM NÃO AMA / NÃO CONHECE / DEUS É AMOR.\nAMOR DEUS SE MANIFESTOU: ENVIOU FILHO ÚNICO PARA TERMOS VIDA.\nAMOR NÃO COMEÇOU EM NÓS / DEUS NOS AMOU E ENVIOU FILHO POR NOSSOS PECADOS.",
  "1Jo 5,1-6": "QUEM CRÊ JESUS É CRISTO / NASCEU DE DEUS.\nQUEM AMA PAI / AMA FILHOS DELE.\nAMAR DEUS = GUARDAR MANDAMENTOS / NÃO SÃO PESADOS.\nQUEM NASCE DE DEUS VENCE MUNDO / VITÓRIA É NOSSA FÉ.\nQUEM VENCE? QUEM CRÊ JESUS FILHO DE DEUS.\nJESUS VEIO PELA ÁGUA E SANGUE / ESPÍRITO TESTEMUNHA.",

  "1Pd 1,17-21": "SE VOCÊS CHAMAM DE PAI AQUELE QUE JULGA SEM PARCIALIDADE / VIVER COM RESPEITO DURANTE PEREGRINAÇÃO.\nVOCÊS FORAM RESGATADOS NÃO COM PRATA OU OURO / MAS SANGUE PRECIOSO CRISTO / CORDEIRO SEM DEFEITO.\nDEUS RESSUSCITOU E GLORIFICOU CRISTO / FÉ E ESPERANÇA DE VOCÊS ESTÃO EM DEUS.",
  "1Pd 1,3-9": "BENDITO DEUS / POR MISERICÓRDIA NOS GEROU DE NOVO PELA RESSURREIÇÃO JESUS / PARA ESPERANÇA VIVA / HERANÇA QUE NÃO SE CORROMPE.\nVOCÊS GUARDADOS PELA FÉ / MESMO AGORA PASSANDO PROVAÇÕES.\nFÉ PROVADA MAIS PRECIOSA QUE OURO.\nSEM TER VISTO JESUS / VOCÊS AMAM; SEM VER AGORA / CREEM / ALEGRIA INDIZÍVEL / ALCANÇAR SALVAÇÃO.",
  "1Pd 2,20-25": "SE SOFRER POR FAZER BEM E SUPORTAR / ISSO AGRADA DEUS.\nCRISTO SOFREU POR VOCÊS / DEIXOU EXEMPLO / SIGAM PASSOS.\nELE NÃO PECOU / NÃO RESPONDEU INSULTO COM INSULTO / ENTREGOU-SE A QUEM JULGA JUSTO.\nCARREGOU NOSSOS PECADOS NO CORPO NA CRUZ / PARA MORRERMOS AO PECADO E VIVERMOS JUSTIÇA.\nVOCÊS ERAM OVELHAS PERDIDAS / AGORA VOLTARAM PASTOR E GUARDIÃO.",
  "1Pd 2,4-9": "APROXIMAR DE CRISTO / PEDRA VIVA REJEITADA POR HUMANOS / ESCOLHIDA DEUS.\nVOCÊS TAMBÉM PEDRAS VIVAS / CONSTRUIR CASA ESPIRITUAL / SACERDÓCIO SANTO.\nCRISTO PEDRA PRINCIPAL / QUEM CRÊ NÃO SERÁ CONFUNDIDO.\nVOCÊS RAÇA ESCOLHIDA / SACERDÓCIO REAL / NAÇÃO SANTA / POVO DE DEUS / ANUNCIAR MARAVILHAS DAQUELE QUE CHAMOU DAS TREVAS PARA LUZ.",
  "1Pd 3,15-18": "NO CORAÇÃO / RECONHECER CRISTO SENHOR.\nSEMPRE PRONTOS PARA EXPLICAR ESPERANÇA / MAS COM MANSIDÃO E RESPEITO / CONSCIÊNCIA BOA.\nMELHOR SOFRER POR FAZER BEM QUE POR FAZER MAL.\nCRISTO MORREU UMA VEZ PELOS PECADOS / JUSTO PELOS INJUSTOS / PARA CONDUZIR VOCÊS A DEUS.",
  "1Pd 3,18-22": "CRISTO MORREU UMA VEZ PELOS PECADOS / JUSTO PELOS INJUSTOS / PARA LEVAR NÓS A DEUS.\nMORTO NA CARNE / VIVIFICADO NO ESPÍRITO.\nNOÉ E POUCOS SALVOS ATRAVÉS ÁGUA / ISSO FIGURA BATISMO QUE AGORA SALVA / NÃO LIMPEZA EXTERNA / MAS CONSCIÊNCIA VOLTADA A DEUS PELA RESSURREIÇÃO JESUS.\nCRISTO ESTÁ À DIREITA DEUS / PODERES SUBMETIDOS.",

  "1Tm 1,12-17": "PAULO AGRADECER CRISTO / CONSIDEROU-ME FIEL / COLOCOU NO MINISTÉRIO / EU ANTES BLASFEMO E PERSEGUIDOR / MAS RECEBI MISERICÓRDIA POR AGIR NA IGNORÂNCIA.\nGRAÇA SENHOR SUPERABUNDOU COM FÉ E AMOR.\nCRISTO JESUS VEIO MUNDO SALVAR PECADORES / EU PRIMEIRO.\nEM MIM JESUS MOSTRAR PACIÊNCIA / EXEMPLO PARA QUEM VAI CRER.\nAO REI ETERNO / HONRA E GLÓRIA.",
  "1Tm 2,1-8": "ANTES DE TUDO / FAZER SÚPLICAS / ORAÇÕES / INTERCESSÕES / AGRADECIMENTOS POR TODOS / INCLUSIVE AUTORIDADES / PARA VIDA PACÍFICA E DIGNA.\nDEUS QUER TODOS SALVOS / CONHECER VERDADE.\nUM SÓ DEUS / UM MEDIADOR ENTRE DEUS E HUMANIDADE: CRISTO JESUS / ENTREGOU-SE POR TODOS.\nPAULO FOI CONSTITUÍDO PREGADOR.\nHOMENS ORAR EM TODO LUGAR / MÃOS SANTAS / SEM IRA.",
  "1Tm 6,11-16": "HOMEM DE DEUS / FUGIR GANÂNCIA E PECADO / BUSCAR JUSTIÇA / PIEDADE / FÉ / AMOR / PERSEVERANÇA / MANSIDÃO.\nCOMBATER BOM COMBATE DA FÉ / AGARRAR VIDA ETERNA.\nGUARDAR MANDAMENTO SEM MANCHA ATÉ MANIFESTAÇÃO JESUS CRISTO.\nDEUS ÚNICO SOBERANO / REI DOS REIS / SENHOR DOS SENHORES / IMORTAL / HABITA LUZ INACESSÍVEL / HONRA E PODER.",

  "1Ts 1,1-5": "PAULO, SILVANO, TIMÓTEO / À IGREJA TESSALÔNICA / GRAÇA E PAZ.\nSEMPRE AGRADECER DEUS POR VOCÊS / LEMBRAR OBRA DA FÉ / ESFORÇO DO AMOR / FIRMEZA DA ESPERANÇA EM JESUS.\nSABEMOS DEUS ESCOLHEU VOCÊS / EVANGELHO NÃO CHEGOU SÓ PALAVRAS / MAS PODER / ESPÍRITO SANTO / CONVICÇÃO.",
  "1Ts 1,5-10": "EVANGELHO CHEGOU COM PODER E ESPÍRITO.\nVOCÊS IMITARAM NÓS E SENHOR / RECEBERAM PALAVRA EM TRIBULAÇÃO COM ALEGRIA ESPÍRITO.\nVIRARAM EXEMPLO PARA CRENTES / FÉ SE ESPALHOU.\nPESSOAS CONTAM COMO VOCÊS ABANDONARAM ÍDOLOS / SERVIR DEUS VIVO / ESPERAR FILHO DO CÉU / JESUS RESSUSCITADO QUE LIVRA DA IRA.",
  "1Ts 2,7-9.13": "ENTRE VOCÊS / NÓS FOMOS DELICADOS COMO MÃE CUIDA FILHOS.\nAMANDO VOCÊS / QUERÍAMOS DAR NÃO SÓ EVANGELHO / MAS PRÓPRIA VIDA.\nTRABALHAMOS DIA E NOITE PARA NÃO PESAR / ENQUANTO ANUNCIÁVAMOS EVANGELHO.\nAGRADECER DEUS PORQUE VOCÊS RECEBERAM PALAVRA NÃO COMO PALAVRA HUMANA / MAS COMO PALAVRA DE DEUS QUE AGE EM QUEM CRÊ.",
  "1Ts 3,12–4,2": "SENHOR FAZER AMOR DE VOCÊS CRESCER E TRANSBORDAR UNS PELOS OUTROS E POR TODOS.\nFORTALECER CORAÇÕES EM SANTIDADE DIANTE PAI / NA VINDA JESUS COM SANTOS.\nIRMÃOS / VOCÊS APRENDERAM COMO VIVER PARA AGRADAR DEUS / CONTINUAR PROGREDIR.\nVOCÊS CONHECEM INSTRUÇÕES DADAS EM NOME JESUS.",
  "1Ts 4,13-18": "IRMÃOS / NÃO QUEREMOS IGNORÂNCIA SOBRE QUEM MORREU / PARA NÃO ENTRISTECER COMO QUEM NÃO TEM ESPERANÇA.\nSE CREMOS JESUS MORREU E RESSUSCITOU / DEUS TRARÁ COM ELE OS QUE MORRERAM.\nSENHOR DESCERÁ / MORTOS EM CRISTO RESSUSCITARÃO / VIVOS SERÃO REUNIDOS COM ELES / ESTAREMOS SEMPRE COM SENHOR.\nCONSOLAR UNS AOS OUTROS COM ESSAS PALAVRAS.",
  "1Ts 5,1-6": "SOBRE TEMPOS E MOMENTOS / NÃO PRECISA ESCREVER / DIA SENHOR VEM COMO LADRÃO À NOITE.\nQUANDO DISSEREM PAZ E SEGURANÇA / DE REPENTE DESTRUIÇÃO.\nMAS VOCÊS NÃO ESTÃO TREVAS / SÃO FILHOS LUZ E DIA.\nPORTANTO NÃO DORMIR COMO OUTROS / VIGIAR E SER SÓBRIOS.",
  "1Ts 5,16-24": "SEMPRE ALEGRAR.\nORAR SEM CESSAR.\nEM TUDO AGRADECER / VONTADE DEUS EM CRISTO.\nNÃO APAGAR ESPÍRITO / NÃO DESPREZAR PROFECIAS / EXAMINAR TUDO / GUARDAR O BEM / AFASTAR DE TODO MAL.\nDEUS DA PAZ SANTIFICAR VOCÊS COMPLETAMENTE / ELE FIEL / FARÁ.",

  "2Cor 1,18-22": "DEUS É FIEL / NOSSA PALAVRA NÃO É SIM E NÃO AO MESMO TEMPO.\nJESUS CRISTO NÃO FOI SIM E NÃO / NELE SEMPRE SIM.\nTODAS PROMESSAS DEUS ENCONTRAM SIM EM CRISTO / POR ELE DIZEMOS AMÉM PARA GLÓRIA DEUS.\nDEUS NOS FIRMA EM CRISTO / NOS UNGIU / MARCOU SELO / DEU ESPÍRITO COMO GARANTIA.",
  "2Cor 12,7-10": "PAULO: PARA NÃO ME EXALTAR / FOI-ME DADO ESPINHO NA CARNE / MENSAGEIRO QUE ME HUMILHA.\nTRÊS VEZES PEDI SENHOR TIRAR.\nELE RESPONDEU: MINHA GRAÇA BASTA / PODER SE APERFEIÇOA NA FRAQUEZA.\nENTÃO EU ME ALEGRO NAS FRAQUEZAS POR CRISTO / PORQUE QUANDO FRACO / ENTÃO FORTE.",
  "2Cor 13,11-13": "IRMÃOS / ALEGREM-SE / BUSQUEM PERFEIÇÃO / ANIMEM-SE / TENHAM MESMO PENSAMENTO / VIVAM EM PAZ.\nDEUS AMOR E PAZ ESTARÁ COM VOCÊS.\nSAUDAR UNS AOS OUTROS.\nGRAÇA JESUS CRISTO / AMOR DEUS / COMUNHÃO ESPÍRITO SANTO COM TODOS.",
  "2Cor 3,1-6": "NÓS PRECISAMOS CARTAS RECOMENDAÇÃO?\nVOCÊS SÃO NOSSA CARTA / ESCRITA CORAÇÕES / CONHECIDA POR TODOS.\nCARTA DE CRISTO / NÃO ESCRITA TINTA / MAS ESPÍRITO DEUS VIVO / NÃO PEDRA / MAS CORAÇÃO.\nNOSSA CAPACIDADE VEM DE DEUS / ELE NOS FEZ MINISTROS NOVA ALIANÇA / NÃO LETRA QUE MATA / MAS ESPÍRITO QUE DÁ VIDA.",
  "2Cor 4,13–5,1": "TEMOS MESMO ESPÍRITO FÉ / CREMOS E POR ISSO FALAMOS.\nQUEM RESSUSCITOU JESUS / TAMBÉM NOS RESSUSCITARÁ E COLOCARÁ COM VOCÊS DIANTE DELE.\nGRAÇA SE ESPALHAR / AGRADECIMENTO AUMENTAR.\nNÃO DESANIMAR: CORPO EXTERIOR SE DESGASTA / INTERIOR RENOVAR DIA A DIA.\nSOFRIMENTO MOMENTÂNEO PREPARA GLÓRIA ETERNA.\nSE NOSSA TENDA TERRENA DESTRUIR / TEMOS CASA DE DEUS ETERNA.",
  "2Cor 4,6-11": "DEUS QUE DISSE LUZ BRILHAR ESCURIDÃO / FEZ LUZ BRILHAR CORAÇÕES / CONHECER GLÓRIA EM CRISTO.\nTEMOS TESOURO EM VASOS DE BARRO / PARA MOSTRAR PODER VEM DE DEUS / NÃO DE NÓS.\nAFLITOS MAS NÃO ESMAGADOS / PERPLEXOS MAS NÃO DESESPERADOS / PERSEGUIDOS MAS NÃO ABANDONADOS / ABATIDOS MAS NÃO DESTRUÍDOS.\nCARREGAMOS MORTE JESUS NO CORPO / PARA VIDA JESUS SE MANIFESTAR.",
  "2Cor 5,14-17": "AMOR DE CRISTO NOS MOVE / UM MORREU POR TODOS / LOGO TODOS MORRERAM.\nELE MORREU POR TODOS / PARA QUEM VIVE NÃO VIVER MAIS PARA SI / MAS PARA AQUELE QUE MORREU E RESSUSCITOU.\nNÃO JULGAR MAIS SEGUNDO CRITÉRIO HUMANO.\nQUEM ESTÁ EM CRISTO / NOVA CRIAÇÃO / COISAS ANTIGAS PASSARAM / NOVO CHEGOU.",
  "2Cor 5,17-21": "QUEM ESTÁ EM CRISTO / NOVA CRIAÇÃO.\nDEUS NOS RECONCILIOU CONSIGO POR CRISTO / DEU MINISTÉRIO RECONCILIAÇÃO.\nDEUS EM CRISTO RECONCILIAR MUNDO / NÃO CONTAR PECADOS / CONFIAR PALAVRA RECONCILIAÇÃO.\nSOMOS EMBAIXADORES DE CRISTO / DEUS APELA POR NÓS: RECONCILIEM-SE COM DEUS.\nCRISTO SEM PECADO / FEITO OFERTA POR NÓS / PARA NELE SERMOS JUSTIÇA DEUS.",
  "2Cor 5,6-10": "SEMPRE CONFIANTES / ENQUANTO NO CORPO / CAMINHAMOS LONGE DA VISÃO PLENA SENHOR.\nCAMINHAMOS PELA FÉ / NÃO PELO QUE VEMOS.\nPREFERÍAMOS ESTAR COM SENHOR / MAS NOSSO OBJETIVO É AGRADAR ELE / PRESENTES OU AUSENTES.\nTODOS COMPARECER DIANTE TRIBUNAL CRISTO / RECEBER SEGUNDO O QUE FEZ.",
  "2Cor 8,7.9.13-15": "COMO VOCÊS ABUNDAM EM FÉ / PALAVRA / CONHECIMENTO / ZELO / AMOR / ABUNDEM TAMBÉM NA GENEROSIDADE.\nVOCÊS CONHECEM GRAÇA JESUS: SENDO RICO / POR VOCÊS SE FEZ POBRE / PARA ENRIQUECER VOCÊS.\nNÃO PARA ALIVIAR OUTROS E SOBRECARREGAR VOCÊS / MAS BUSCAR IGUALDADE.\nAGORA ABUNDÂNCIA DE VOCÊS SUPRIR FALTA DELES / DEPOIS O CONTRÁRIO / PARA HAVER EQUILÍBRIO.",

  "2Pd 3,8-14": "PARA SENHOR / UM DIA COMO MIL ANOS / MIL ANOS COMO UM DIA.\nSENHOR NÃO DEMORA PROMESSA / É PACIENTE / QUER NINGUÉM PEREÇA / TODOS CONVERTER.\nDIA SENHOR VIRÁ COMO LADRÃO / CÉUS E TERRA PASSARÃO.\nPORTANTO VIVER EM SANTIDADE E PIEDADE / ESPERAR NOVOS CÉUS E NOVA TERRA ONDE JUSTIÇA HABITA.\nESFORÇAR PARA SER ENCONTRADOS EM PAZ.",

  "2Tm 1,6-8.13-14": "PAULO A TIMÓTEO: REAVIVAR DOM DEUS RECEBIDO.\nDEUS NÃO DEU ESPÍRITO MEDO / MAS PODER / AMOR / EQUILÍBRIO.\nNÃO SE ENVERGONHAR TESTEMUNHO SENHOR NEM DE MIM PRISIONEIRO / PARTICIPAR SOFRIMENTO PELO EVANGELHO COM FORÇA DEUS.\nGUARDAR MODELO PALAVRAS SAUDÁVEIS COM FÉ E AMOR.\nGUARDAR BOM DEPÓSITO PELO ESPÍRITO SANTO.",
  "2Tm 1,8-10": "NÃO SE ENVERGONHAR TESTEMUNHO SENHOR / PARTICIPAR SOFRIMENTO EVANGELHO COM PODER DEUS.\nDEUS NOS SALVOU E CHAMOU VOCAÇÃO SANTA / NÃO POR OBRAS / MAS GRAÇA E PROPÓSITO.\nGRAÇA DADA EM CRISTO ANTES TEMPOS / AGORA MANIFESTADA JESUS SALVADOR / ELE DESTRUIU MORTE / FEZ VIDA E IMORTALIDADE BRILHAR PELO EVANGELHO.",
  "2Tm 2,8-13": "LEMBRAR JESUS CRISTO / DESCENDENTE DAVI / RESSUSCITADO DOS MORTOS / ESTE É MEU EVANGELHO.\nPOR ELE SOFRO ATÉ CADEIAS / MAS PALAVRA DEUS NÃO ESTÁ PRESA.\nSUPORTO TUDO PELOS ELEITOS / PARA ALCANÇAREM SALVAÇÃO.\nSE MORREMOS COM ELE / VIVEREMOS; SE PERSEVERAMOS / REINAREMOS; SE NEGAMOS / ELE NEGARÁ; SE SOMOS INFIEIS / ELE PERMANECE FIEL.",
  "2Tm 3,14–4,2": "TIMÓTEO / PERMANECER NO QUE APRENDEU / DESDE CRIANÇA CONHECE ESCRITURAS QUE DÃO SABEDORIA PARA SALVAÇÃO PELA FÉ EM CRISTO.\nTODA ESCRITURA INSPIRADA POR DEUS / ÚTIL ENSINAR / CORRIGIR / EDUCAR JUSTIÇA / PREPARAR PESSOA DE DEUS.\nDIANTE DEUS E CRISTO / EU ORDENO: PROCLAMAR PALAVRA / INSISTIR OPORTUNA E INOPORTUNAMENTE / CORRIGIR / REPREENDER / ENCORAJAR COM PACIÊNCIA.",
  "2Tm 4,6-8.16-18": "PAULO: MINHA VIDA JÁ SENDO DERRAMADA / HORA PARTIDA PRÓXIMA.\nCOMBATI BOM COMBATE / COMPLETEI CORRIDA / GUARDEI FÉ.\nAGORA COROA JUSTIÇA ME ESPERA / SENHOR DARÁ A MIM E A TODOS QUE ESPERAM SUA VINDA.\nNA PRIMEIRA DEFESA NINGUÉM ME APOIOU / MAS SENHOR FICOU AO MEU LADO / DEU FORÇA.\nSENHOR ME LIVRARÁ DE TODO MAL / LEVARÁ REINO CELESTE.",

  "2Ts 1,11–2,2": "NÓS SEMPRE ORAR POR VOCÊS / DEUS TORNAR VOCÊS DIGNOS CHAMADO / REALIZAR TODO BEM E OBRA DA FÉ / NOME JESUS SER GLORIFICADO.\nSOBRE VINDA SENHOR E NOSSA REUNIÃO COM ELE / NÃO SE DEIXAR ABALAR OU ASSUSTAR POR ESPÍRITO / PALAVRA / CARTA DIZENDO DIA SENHOR JÁ CHEGOU.",
  "2Ts 2,16–3,5": "JESUS CRISTO E DEUS PAI / QUE NOS AMOU E DEU CONSOLAÇÃO E BOA ESPERANÇA / CONSOLAR CORAÇÕES / FORTALECER EM TODO BEM.\nOREM POR NÓS / PALAVRA SENHOR SE ESPALHAR E SER HONRADA / SER LIVRES DE HOMENS MAUS.\nSENHOR É FIEL / FORTALECER E GUARDAR DO MAL.\nSENHOR DIRIGIR CORAÇÕES AO AMOR DEUS E PERSEVERANÇA CRISTO.",
  "2Ts 3,7-12": "VOCÊS SABEM COMO IMITAR NÓS / NÃO VIVEMOS OCIOSOS / TRABALHAMOS DIA E NOITE PARA NÃO PESAR NINGUÉM / AINDA QUE TÍNHAMOS DIREITO APOIO.\nREGRA: QUEM NÃO QUER TRABALHAR / NÃO COMER.\nOUVIMOS ALGUNS SEM TRABALHAR / METENDO-SE VIDA OUTROS.\nA ESSES ORDENAMOS: TRABALHAR TRANQUILAMENTE / COMER O PRÓPRIO PÃO.",

  "Ap 1,5-8": "JESUS CRISTO / TESTEMUNHA FIEL / PRIMEIRO RESSUSCITADO / SOBERANO REIS TERRA.\nELE NOS AMA / LIBERTOU PECADOS PELO SANGUE / FEZ DE NÓS REINO E SACERDOTES PARA DEUS PAI.\nELE VEM COM NUVENS / TODOS VERÃO.\nDEUS: EU ALFA E ÔMEGA / AQUELE QUE É / ERA / VEM / TODO-PODEROSO.",
  "Ap 1,9-11.12-13.17-19": "JOÃO / IRMÃO E COMPANHEIRO NA TRIBULAÇÃO / REINO / PERSEVERANÇA / ESTAVA NA ILHA PATMOS POR CAUSA PALAVRA.\nNO DIA SENHOR / ESPÍRITO TOMAR / OUVIR VOZ FORTE MANDAR ESCREVER.\nVIRAR / VER CANDEEIROS E ALGUÉM COMO FILHO HOMEM.\nJOÃO CAIR COMO MORTO.\nELE TOCAR: NÃO TENHA MEDO / EU PRIMEIRO E ÚLTIMO / VIVO / ESTIVE MORTO / AGORA VIVO PARA SEMPRE / TENHO CHAVES MORTE.\nESCREVA O QUE VIU.",
  "Ap 21,1-5": "JOÃO VER NOVO CÉU E NOVA TERRA / PRIMEIROS PASSARAM / MAR NÃO MAIS.\nVER CIDADE SANTA / NOVA JERUSALÉM DESCER DE DEUS / COMO NOIVA PREPARADA.\nVOZ TRONO: MORADA DEUS COM HUMANIDADE / ELE HABITAR COM ELES / ELES POVO DELE.\nDEUS ENXUGAR TODA LÁGRIMA / MORTE NÃO MAIS / LUTO / CHORO / DOR NÃO MAIS.\nAQUELE NO TRONO: EIS QUE FAÇO NOVAS TODAS COISAS.",
  "Ap 21,10-14.22-23": "ANJO LEVAR JOÃO EM ESPÍRITO A GRANDE MONTE / MOSTRAR JERUSALÉM SANTA DESCENDO DE DEUS / CHEIA GLÓRIA.\nMURALHA GRANDE / DOZE PORTAS COM NOMES TRIBOS ISRAEL / DOZE FUNDAMENTOS COM NOMES APÓSTOLOS.\nTEMPLO NÃO VI / SENHOR DEUS TODO-PODEROSO E CORDEIRO SÃO TEMPLO.\nCIDADE NÃO PRECISA SOL NEM LUA / GLÓRIA DEUS ILUMINA / CORDEIRO É LÂMPADA.",
  "Ap 5,11-14": "JOÃO OUVIR MILHÕES ANJOS AO REDOR TRONO / SERES VIVOS / ANCIÃOS.\nELES PROCLAMAR: CORDEIRO QUE FOI MORTO É DIGNO RECEBER PODER / RIQUEZA / SABEDORIA / FORÇA / HONRA / GLÓRIA / LOUVOR.\nTODA CRIAÇÃO CÉU / TERRA / MAR LOUVAR DEUS NO TRONO E CORDEIRO.\nSERES DIZER AMÉM / ANCIÃOS ADORAR.",
  "Ap 7,9.14-17": "JOÃO VER MULTIDÃO IMENSA DE TODAS NAÇÕES / POVOS / LÍNGUAS / DIANTE TRONO E CORDEIRO / ROUPAS BRANCAS / PALMAS.\nELES VIERAM GRANDE TRIBULAÇÃO / LAVARAM ROUPAS NO SANGUE CORDEIRO.\nSERVEM DEUS DIA E NOITE / ELE ABRIGAR.\nNÃO TER FOME NEM SEDE / SOL NÃO QUEIMAR.\nCORDEIRO SERÁ PASTOR / CONDUZIR FONTES ÁGUA VIDA / DEUS ENXUGAR LÁGRIMAS.",

  "At 1,1-11": "LUCAS A TEÓFILO: JESUS DEPOIS SOFRER / MOSTROU-SE VIVO MUITAS PROVAS / QUARENTA DIAS / FALAR REINO.\nMANDAR DISCÍPULOS ESPERAR PROMESSA PAI / BATISMO ESPÍRITO SANTO.\nELES PERGUNTAR SOBRE RESTAURAR REINO ISRAEL.\nJESUS: TEMPOS PAI DECIDE / VOCÊS RECEBERÃO PODER ESPÍRITO / SERÃO TESTEMUNHAS JERUSALÉM / JUDEIA / SAMARIA / ATÉ FIM TERRA.\nJESUS SER ELEVADO / NUVEM ESCONDER.\nANJOS: POR QUE OLHAR CÉU? ELE VOLTARÁ.",
  "At 10,25-26.34-35.44-48": "(CENÁRIO: casa Cornélio; Pedro chega; gentios reunidos)\nCORNÉLIO CAIR PÉS PEDRO / PEDRO LEVANTAR: EU TAMBÉM HUMANO.\nPEDRO: DEUS NÃO FAZ ACEPÇÃO PESSOAS / EM TODA NAÇÃO QUEM O RESPEITA E PRATICA JUSTIÇA É ACEITO.\nENQUANTO PEDRO FALAR / ESPÍRITO SANTO DESCER SOBRE TODOS OUVINTES / JUDEUS ADMIRAR GENTIOS RECEBEREM DOM.\nPEDRO: QUEM PODE IMPEDIR ÁGUA BATISMO?\nMANDAR BATIZAR EM NOME JESUS.",
  "At 10,34-38": "PEDRO: AGORA ENTENDO / DEUS NÃO FAZ ACEPÇÃO PESSOAS / EM TODA NAÇÃO QUEM TEME E FAZ JUSTIÇA É ACEITO.\nDEUS ENVIOU PALAVRA A ISRAEL / PAZ POR JESUS CRISTO / SENHOR DE TODOS.\nVOCÊS SABEM O QUE ACONTECEU / DEPOIS BATISMO JOÃO.\nDEUS UNGIU JESUS NAZARÉ COM ESPÍRITO SANTO E PODER / ELE PASSOU FAZENDO BEM / CURANDO OPRIMIDOS / DEUS ESTAVA COM ELE.",
  "At 10,34.37-43": "PEDRO: DEUS NÃO FAZ ACEPÇÃO.\nVOCÊS SABEM O QUE ACONTECEU COM JESUS NAZARÉ / UNGIDO ESPÍRITO E PODER / FAZER BEM E CURAR.\nNÓS TESTEMUNHAS / ELES MATARAM PENDURANDO MADEIRO / DEUS RESSUSCITOU TERCEIRO DIA / FEZ APARECER A TESTEMUNHAS ESCOLHIDAS.\nJESUS MANDOU PREGAR / ELE JUIZ VIVOS E MORTOS.\nPROFETAS TESTEMUNHAM: QUEM CRÊ NELE RECEBE PERDÃO.",
  "At 13,14.43-52": "PAULO E BARNABÉ EM ANTIOQUIA / NO SÁBADO ENSINAR.\nMUITOS JUDEUS E CONVERTIDOS SEGUIR / ELES EXORTAR PERMANECER GRAÇA.\nOUTRO SÁBADO QUASE CIDADE TODA OUVIR PALAVRA / ALGUNS CHEIOS INVEJA CONTRADIZER.\nPAULO E BARNABÉ: ERA NECESSÁRIO ANUNCIAR PRIMEIRO A VOCÊS / COMO REJEITAM / VOLTAMOS AOS GENTIOS / SENHOR MANDOU SER LUZ NAÇÕES.\nGENTIOS ALEGRAR / PALAVRA ESPALHAR / DISCÍPULOS CHEIOS ALEGRIA E ESPÍRITO.",
  "At 13,16-17.22-25": "PAULO LEVANTAR / FALAR: DEUS ESCOLHEU NOSSOS PAIS / FEZ POVO CRESCER / LIBERTOU EGITO.\nDEPOIS LEVANTOU DAVI / HOMEM SEGUNDO CORAÇÃO DEUS / FAZER VONTADE.\nDA DESCENDÊNCIA DAVI / DEUS TROUXE JESUS SALVADOR CONFORME PROMESSA.\nANTES JESUS CHEGAR / JOÃO PREGOU BATISMO CONVERSÃO.\nJOÃO: EU NÃO SOU QUEM VOCÊS PENSAM / DEPOIS DE MIM VEM AQUELE QUE NÃO SOU DIGNO DESATAR SANDÁLIA.",
  "At 14,21-27": "PAULO E BARNABÉ ANUNCIAR EVANGELHO / FAZER MUITOS DISCÍPULOS.\nVOLTAR CIDADES / FORTALECER DISCÍPULOS / ENCORAJAR PERMANECER FÉ / DIZER PRECISAMOS PASSAR TRIBULAÇÕES PARA ENTRAR REINO.\nNOMEAR PRESBÍTEROS EM CADA IGREJA / ORAR / JEJUAR / CONFIAR AO SENHOR.\nVOLTAR ANTIOQUIA / REUNIR IGREJA / CONTAR TUDO QUE DEUS FEZ / ABRIU PORTA FÉ AOS GENTIOS.",
  "At 15,1-2.22-29": "ALGUNS ENSINAR: GENTIOS PRECISAM CIRCUNCISÃO PARA SALVAÇÃO.\nPAULO E BARNABÉ DISCUTIR / IGREJA ENVIAR A JERUSALÉM.\nAPÓSTOLOS E ANCIÃOS COM TODA IGREJA DECIDIR ENVIAR CARTA.\nESPÍRITO SANTO E NÓS DECIDIMOS NÃO IMPOR PESO ALÉM NECESSÁRIO / EVITAR IDOLATRIA / SANGUE / CARNE SUFOCADA / IMORALIDADE.\nFIQUEM BEM.",
  "At 2,1-11": "(CENÁRIO: todos reunidos; som vento; línguas fogo; multidão de nações)\nPENTECOSTES / DISCÍPULOS JUNTOS.\nSOM DO CÉU COMO VENTO FORTE / CASA ENCHER.\nLÍNGUAS COMO FOGO / POUSAR SOBRE CADA UM.\nTODOS CHEIOS ESPÍRITO SANTO / FALAR OUTRAS LÍNGUAS CONFORME ESPÍRITO DAVA.\nJUDEUS DE MUITAS NAÇÕES OUVIR / CADA UM NA PRÓPRIA LÍNGUA / ESPANTADOS.\nELES OUVEM DISCÍPULOS ANUNCIAR GRANDES OBRAS DEUS.",
  "At 2,14.22-28": "PEDRO COM ONZE LEVANTAR / FALAR POVO.\nJESUS NAZARÉ FOI APROVADO POR DEUS COM MILAGRES / VOCÊS SABEM.\nENTREGUE SEGUNDO PLANO DEUS / VOCÊS CRUCIFICARAM POR MÃOS ÍMPIAS.\nDEUS RESSUSCITOU / MORTE NÃO PODIA PRENDER.\nDAVI JÁ DIZIA: SENHOR SEMPRE DIANTE DE MIM / NÃO ABANDONAR MINHA ALMA MORTE / MOSTRAR CAMINHOS VIDA.",
  "At 2,14.36-41": "PEDRO COM ONZE FALAR FORTE.\nTODOS ISRAEL SABER COM CERTEZA: DEUS FEZ SENHOR E CRISTO ESTE JESUS QUE VOCÊS CRUCIFICARAM.\nPOVO CORAÇÃO TOCADO / PERGUNTAR: O QUE FAZER?\nPEDRO: CONVERTER / CADA UM SER BATIZADO EM NOME JESUS PARA PERDÃO / RECEBER ESPÍRITO SANTO.\nPROMESSA PARA VOCÊS / FILHOS / TODOS LONGE QUE DEUS CHAMAR.\nMUITOS ACOLHERAM PALAVRA / BATIZADOS.",
  "At 2,42-47": "PRIMEIROS CRISTÃOS PERSEVERAR ENSINO APÓSTOLOS / COMUNHÃO / PARTIR PÃO / ORAÇÕES.\nSINAIS E PRODÍGIOS ACONTECER.\nTODOS CRENTES UNIDOS / PARTILHAR BENS CONFORME NECESSIDADE.\nDIARIAMENTE TEMPLO / CASAS PARTIR PÃO COM ALEGRIA / LOUVAR DEUS / TER SIMPATIA POVO.\nSENHOR ACRESCENTAR CADA DIA OS QUE ERAM SALVOS.",
  "At 3,13-15.17-19": "PEDRO: DEUS ABRAÃO / ISAAC / JACÓ GLORIFICOU SERVO JESUS.\nVOCÊS ENTREGARAM E NEGARAM DIANTE PILATOS / NEGARAM SANTO E JUSTO / PEDIRAM ASSASSINO / MATARAM AUTOR DA VIDA.\nDEUS RESSUSCITOU / NÓS TESTEMUNHAS.\nIRMÃOS / SEI QUE AGIRAM POR IGNORÂNCIA / COMO LÍDERES / MAS DEUS CUMPRIU PROFETAS.\nPORTANTO ARREPENDER E CONVERTER / PECADOS APAGADOS.",
  "At 4,32-35": "MULTIDÃO CRENTES / UM SÓ CORAÇÃO E ALMA.\nNINGUÉM DIZER BENS ERAM SÓ SEUS / TUDO PARTILHADO.\nAPÓSTOLOS COM GRANDE PODER TESTEMUNHAR RESSURREIÇÃO JESUS / GRAÇA SOBRE TODOS.\nNÃO HAVIA NECESSITADO / QUEM TINHA TERRAS OU CASAS VENDIA / TRAZIA VALOR AOS APÓSTOLOS / DISTRIBUIR CONFORME NECESSIDADE.",
  "At 4,8-12": "PEDRO CHEIO ESPÍRITO SANTO / FALAR A LÍDERES.\nSE HOJE SOMOS INTERROGADOS POR BEM FEITO A DOENTE / SAIBAM: FOI EM NOME JESUS CRISTO NAZARENO / VOCÊS CRUCIFICARAM / DEUS RESSUSCITOU.\nELE É PEDRA REJEITADA POR CONSTRUTORES / TORNOU-SE PEDRA PRINCIPAL.\nEM NENHUM OUTRO HÁ SALVAÇÃO / NENHUM OUTRO NOME DADO À HUMANIDADE PARA SER SALVA.",
  "At 5,12-16": "MUITOS SINAIS E PRODÍGIOS PELAS MÃOS APÓSTOLOS.\nCRENTES REUNIDOS / POVO ADMIRAR / MAIS HOMENS E MULHERES ADERIR SENHOR.\nLEVAVAM DOENTES ÀS RUAS / ESPERAR ATÉ SOMBRA PEDRO.\nMULTIDÕES CIDADES VIZINHAS TRAZER DOENTES E ATORMENTADOS / TODOS CURADOS.",
  "At 5,27-32.40-41": "GUARDAS LEVAR APÓSTOLOS AO CONSELHO.\nSUMO SACERDOTE: PROIBIMOS ENSINAR NOME JESUS / VOCÊS ENCHERAM JERUSALÉM.\nPEDRO E APÓSTOLOS: É PRECISO OBEDECER A DEUS ANTES QUE HUMANOS.\nDEUS RESSUSCITOU JESUS QUE VOCÊS MATARAM / EXALTOU COMO CHEFE E SALVADOR / DAR CONVERSÃO E PERDÃO.\nNÓS TESTEMUNHAS / E ESPÍRITO SANTO TAMBÉM.\nDEPOIS AÇOITADOS E PROIBIDOS / SAÍRAM ALEGRES POR SOFREREM POR NOME JESUS.",
  "At 6,1-7": "DISCÍPULOS AUMENTAR / HELENISTAS RECLAMAR VIÚVAS ESQUECIDAS DISTRIBUIÇÃO.\nDOZE REUNIR COMUNIDADE: NÃO É BOM ABANDONAR PALAVRA PARA SERVIR MESAS / ESCOLHAM SETE HOMENS REPUTAÇÃO BOA / CHEIOS ESPÍRITO E SABEDORIA.\nNÓS NOS DEDICAR ORAÇÃO E PALAVRA.\nCOMUNIDADE ESCOLHER SETE / APÓSTOLOS ORAR E IMPOR MÃOS.\nPALAVRA DEUS CRESCER / DISCÍPULOS MULTIPLICAR.",
  "At 8,5-8.14-17": "FILIPE DESCER SAMARIA / ANUNCIAR CRISTO.\nMULTIDÃO PRESTAR ATENÇÃO / VER SINAIS / ESPÍRITOS SAIR / PARALÍTICOS E MANCOS CURADOS / GRANDE ALEGRIA CIDADE.\nAPÓSTOLOS JERUSALÉM OUVIR SAMARIA RECEBEU PALAVRA / ENVIAR PEDRO E JOÃO.\nELES ORAR PARA SAMARITANOS RECEBER ESPÍRITO SANTO / IMPOR MÃOS / ELES RECEBER.",
  "At 9,26-31": "SAULO CHEGAR JERUSALÉM / TENTAR JUNTAR DISCÍPULOS / TODOS MEDO / NÃO ACREDITAR CONVERSÃO.\nBARNABÉ PEGAR SAULO / LEVAR APÓSTOLOS / CONTAR COMO VIU SENHOR / JESUS FALOU / SAULO PREGOU COM CORAGEM DAMASCO.\nSAULO FALAR ABERTAMENTE / HELENISTAS QUERER MATAR / IRMÃOS LEVAR CESAREIA / ENVIAR TARSO.\nIGREJA TER PAZ / CRESCER / CAMINHAR TEMOR SENHOR / CONSOLAÇÃO ESPÍRITO.",

  "Cl 1,12-20": "AGRADECER PAI / TORNOU VOCÊS CAPAZES PARTICIPAR HERANÇA SANTOS NA LUZ.\nELE NOS LIBERTOU PODER TREVAS / TRANSFERIU REINO FILHO AMADO / NELE REDENÇÃO E PERDÃO.\nCRISTO IMAGEM DEUS INVISÍVEL / PRIMOGÊNITO CRIAÇÃO / TUDO CRIADO POR ELE E PARA ELE / ELE ANTES DE TUDO / TUDO NELE SUBSISTE.\nELE CABEÇA IGREJA / PRIMOGÊNITO DOS MORTOS / EM TUDO PRIMEIRO.\nDEUS QUIS RECONCILIAR TUDO POR ELE / FAZER PAZ PELO SANGUE CRUZ.",
  "Cl 1,15-20": "CRISTO IMAGEM DEUS INVISÍVEL / PRIMOGÊNITO CRIAÇÃO.\nPOR ELE TUDO CRIADO CÉU E TERRA / VISÍVEL E INVISÍVEL / TUDO POR ELE E PARA ELE.\nELE ANTES DE TUDO / TUDO NELE SE MANTÉM.\nELE CABEÇA CORPO IGREJA / PRINCÍPIO / PRIMOGÊNITO MORTOS.\nDEUS FEZ PLENITUDE HABITAR NELE / RECONCILIAR TUDO / PAZ PELO SANGUE CRUZ.",
  "Cl 1,24-28": "PAULO: ALEGRO NOS SOFRIMENTOS POR VOCÊS / COMPLETO EM MEU CORPO O QUE FALTA ÀS TRIBULAÇÕES DE CRISTO EM FAVOR CORPO / IGREJA.\nDEUS ME FEZ MINISTRO PARA ANUNCIAR PALAVRA PLENAMENTE / MISTÉRIO ESCONDIDO / AGORA REVELADO: CRISTO EM VOCÊS / ESPERANÇA GLÓRIA.\nNÓS ANUNCIAR CRISTO / ADVERTIR E ENSINAR TODOS / APRESENTAR CADA UM MADURO EM CRISTO.",
  "Cl 2,12-14": "NO BATISMO / VOCÊS FORAM SEPULTADOS COM CRISTO / E COM ELE RESSUSCITARAM PELA FÉ NO PODER DEUS QUE O RESSUSCITOU.\nVOCÊS ESTAVAM MORTOS PECADOS / DEUS DEU VIDA COM CRISTO / PERDOOU FALTAS.\nCANCELOU DOCUMENTO DÍVIDA CONTRA NÓS / TIROU DO MEIO / PREGOU NA CRUZ.",
  "Cl 3,1-4 ou 1Cor 5,6-8": "OPÇÃO 1 — SE RESSUSCITARAM COM CRISTO / BUSCAR COISAS DO ALTO / ONDE CRISTO ESTÁ / VIDA ESCONDIDA COM ELE EM DEUS / QUANDO CRISTO APARECER / VOCÊS APARECERÃO NA GLÓRIA.\nOPÇÃO 2 — TIRAR FERMENTO VELHO / SER MASSA NOVA / CRISTO NOSSA PÁSCOA FOI SACRIFICADO / CELEBRAR COM SINCERIDADE E VERDADE.",
  "Cl 3,1-5.9-11": "SE RESSUSCITARAM COM CRISTO / BUSCAR COISAS DO ALTO / NÃO SÓ DA TERRA.\nVOCÊS MORRERAM / VIDA ESCONDIDA COM CRISTO.\nMORTIFICAR O QUE PERTENCE À VELHA VIDA: IMORALIDADE / DESEJOS MAUS / GANÂNCIA.\nNÃO MENTIR / VOCÊS DESPIRAM HOMEM VELHO / VESTIRAM NOVO / RENOVADO À IMAGEM CRIADOR.\nEM CRISTO BARREIRAS CAEM / CRISTO É TUDO EM TODOS.",
  "Cl 3,12-21": "COMO ESCOLHIDOS SANTOS AMADOS / REVESTIR COMPAIXÃO / BONDADE / HUMILDADE / MANSIDÃO / PACIÊNCIA.\nSUPORTAR E PERDOAR COMO SENHOR PERDOOU.\nACIMA DE TUDO / AMOR / VÍNCULO PERFEITO.\nPAZ CRISTO GOVERNAR CORAÇÕES / SER AGRADECIDOS / PALAVRA CRISTO HABITAR RICAMENTE.\nNA VIDA FAMILIAR / RELAÇÕES MARCADAS POR AMOR / RESPEITO / NÃO ASPEREZA / OBEDIÊNCIA NO SENHOR / PAIS NÃO DESANIMAR FILHOS.",

  "Ef 1,17-23": "PAULO ORAR: DEUS DE JESUS CRISTO / PAI GLÓRIA / DAR ESPÍRITO SABEDORIA E REVELAÇÃO / CONHECER ELE.\nILUMINAR OLHOS CORAÇÃO / SABER ESPERANÇA CHAMADO / RIQUEZA HERANÇA / GRANDEZA PODER EM NÓS.\nMESMO PODER RESSUSCITOU CRISTO / SENTOU DIREITA CÉU / ACIMA TODO PODER.\nDEUS TUDO COLOCOU SOB PÉS CRISTO / DEU COMO CABEÇA IGREJA / CORPO DELE.",
  "Ef 1,3-14": "BENDITO DEUS PAI / NOS ABENÇOOU EM CRISTO COM TODA BÊNÇÃO ESPIRITUAL.\nANTES CRIAÇÃO / NOS ESCOLHEU PARA SER SANTOS / PREDESTINOU FILHOS POR JESUS / POR GRAÇA.\nEM CRISTO TEMOS REDENÇÃO PELO SANGUE / PERDÃO / CONHECEMOS MISTÉRIO VONTADE DEUS: REUNIR TUDO EM CRISTO.\nNELE RECEBEMOS HERANÇA / OUVIMOS PALAVRA VERDADE / CREMOS / FOMOS SELADOS ESPÍRITO SANTO / GARANTIA HERANÇA.",
  "Ef 2,13-18": "VOCÊS ANTES LONGE / AGORA EM CRISTO CHEGARAM PERTO PELO SANGUE.\nCRISTO É NOSSA PAZ / DE DOIS POVOS FEZ UM / DERRUBOU MURO INIMIZADE.\nNA CRUZ RECONCILIOU AMBOS COM DEUS EM UM CORPO / MATOU INIMIZADE.\nELE VEIO ANUNCIAR PAZ AOS LONGE E AOS PERTO.\nPOR ELE / TODOS TEMOS ACESSO AO PAI NUM SÓ ESPÍRITO.",
  "Ef 2,4-10": "DEUS RICO EM MISERICÓRDIA / GRANDE AMOR / QUANDO ESTÁVAMOS MORTOS PECADOS / DEU VIDA COM CRISTO / PELA GRAÇA VOCÊS SALVOS.\nRESSUSCITOU E FEZ SENTAR COM CRISTO / PARA MOSTRAR RIQUEZA GRAÇA.\nSALVAÇÃO PELA GRAÇA / MEDIANTE FÉ / NÃO VEM DE NÓS / DOM DEUS / NÃO POR OBRAS PARA NINGUÉM SE GLORIAR.\nSOMOS OBRA DELE / CRIADOS EM CRISTO PARA BOAS OBRAS.",
  "Ef 3,2-3.5-6": "PAULO: VOCÊS OUVIRAM MISSÃO GRAÇA QUE DEUS ME DEU PARA VOCÊS.\nMISTÉRIO ME FOI REVELADO.\nOUTRAS GERAÇÕES NÃO CONHECERAM COMO AGORA ESPÍRITO REVELOU A APÓSTOLOS E PROFETAS.\nMISTÉRIO: GENTIOS SÃO COERDEIROS / MEMBROS DO MESMO CORPO / PARTICIPANTES DA MESMA PROMESSA EM CRISTO PELO EVANGELHO.",
  "Ef 4,1-6": "PAULO PRISIONEIRO SENHOR / PEDIR: VIVER DE MODO DIGNO CHAMADO.\nHUMILDADE / MANSIDÃO / PACIÊNCIA / SUPORTAR UNS AOS OUTROS COM AMOR.\nESFORÇAR MANTER UNIDADE ESPÍRITO PELO VÍNCULO PAZ.\nUM CORPO / UM ESPÍRITO / UMA ESPERANÇA / UM SENHOR / UMA FÉ / UM BATISMO / UM DEUS E PAI DE TODOS.",
  "Ef 4,17.20-24": "PAULO: NÃO VIVER MAIS COMO GENTIOS EM MENTE VAZIA.\nVOCÊS APRENDERAM CRISTO DIFERENTE.\nABANDONAR HOMEM VELHO CORROMPIDO POR DESEJOS.\nRENOVAR MENTE E ESPÍRITO.\nVESTIR HOMEM NOVO / CRIADO SEGUNDO DEUS EM JUSTIÇA E SANTIDADE VERDADE.",
  "Ef 4,30–5,2": "NÃO ENTRISTECER ESPÍRITO SANTO / NELE VOCÊS SELADOS.\nTIRAR AMARGURA / IRA / GRITOS / MALDADE.\nSER BONDOSOS / COMPASSIVOS / PERDOAR UNS AOS OUTROS COMO DEUS PERDOOU EM CRISTO.\nIMITAR DEUS COMO FILHOS AMADOS / CAMINHAR NO AMOR / COMO CRISTO AMOU E SE ENTREGOU POR NÓS.",
  "Ef 5,15-20": "CUIDADO COMO VIVEM / NÃO COMO INSENSATOS / MAS SÁBIOS / APROVEITAR TEMPO / DIAS MAUS.\nNÃO SER SEM JUÍZO / ENTENDER VONTADE SENHOR.\nNÃO EMBRIAGAR VINHO / ENCHER-SE ESPÍRITO.\nFALAR SALMOS / HINOS / CÂNTICOS / CANTAR SENHOR CORAÇÃO.\nSEMPRE AGRADECER DEUS PAI POR TUDO EM NOME JESUS.",
  "Ef 5,21-32": "SUBMETER-SE UNS AOS OUTROS NO RESPEITO A CRISTO.\nVIDA MATRIMONIAL DEVE ESPELHAR AMOR SACRIFICIAL DE CRISTO PELA IGREJA.\nMARIDO AMAR ESPOSA COMO PRÓPRIO CORPO / CRISTO AMOU IGREJA E SE ENTREGOU POR ELA.\nHOMEM DEIXAR PAI E MÃE / UNIR ESPOSA / DOIS UMA CARNE.\nMISTÉRIO GRANDE / REFERE-SE A CRISTO E IGREJA.",
  "Ef 5,8-14": "ANTES VOCÊS ERAM TREVAS / AGORA LUZ NO SENHOR / VIVER COMO FILHOS LUZ.\nFRUTO LUZ: BONDADE / JUSTIÇA / VERDADE.\nDISCERNIR O QUE AGRADA SENHOR / NÃO PARTICIPAR OBRAS ESTÉREIS TREVAS / MAS EXPOR À LUZ.\nTUDO QUE LUZ REVELA TORNA-SE VISÍVEL.\nACORDA QUEM DORME / LEVANTA DOS MORTOS / CRISTO TE ILUMINAR.",

  "Fl 1,20-24.27": "PAULO ESPERAR NÃO SE ENVERGONHAR / CRISTO SER GLORIFICADO EM MEU CORPO / VIDA OU MORTE.\nPARA MIM VIVER É CRISTO / MORRER É LUCRO.\nDESEJO PARTIR E ESTAR COM CRISTO / MUITO MELHOR / MAS PERMANECER É NECESSÁRIO POR VOCÊS.\nSEJA COMO FOR / VIVER DE MODO DIGNO EVANGELHO CRISTO.",
  "Fl 1,4-6.8-11": "PAULO ORAR COM ALEGRIA POR VOCÊS / POR PARTICIPAÇÃO NO EVANGELHO.\nCONFIO: AQUELE QUE COMEÇOU BOA OBRA EM VOCÊS / COMPLETARÁ ATÉ DIA JESUS.\nDEUS TESTEMUNHA COMO SINTO SAUDADE COM AMOR CRISTO.\nORO PARA AMOR CRESCER EM CONHECIMENTO E DISCERNIMENTO / ESCOLHER O MELHOR / CHEIOS FRUTOS JUSTIÇA PARA GLÓRIA DEUS.",
  "Fl 2,1-11": "SE HÁ CONSOLAÇÃO EM CRISTO / COMUNHÃO ESPÍRITO / COMPAIXÃO / COMPLETEM MINHA ALEGRIA: MESMO AMOR / UNIDOS.\nNADA POR VAIDADE / HUMILDADE CONSIDERAR OUTRO SUPERIOR / CUIDAR INTERESSE DOS OUTROS.\nTER MESMO SENTIMENTO CRISTO: SENDO DEUS / NÃO SE AGARROU AO PRIVILÉGIO / ESVAZIOU-SE / FORMA SERVO / HUMILHOU-SE ATÉ MORTE CRUZ.\nPOR ISSO DEUS EXALTOU / TODO JOELHO SE DOBRAR / TODA LÍNGUA CONFESSAR JESUS CRISTO SENHOR.",
  "Fl 2,6-11": "CRISTO SENDO DE CONDIÇÃO DIVINA / NÃO SE AGARROU AO SER IGUAL DEUS.\nESVAZIOU-SE / TOMOU FORMA SERVO / FEZ-SE HUMANO.\nHUMILHOU-SE / OBEDECEU ATÉ MORTE / MORTE CRUZ.\nPOR ISSO DEUS O EXALTOU / DEU NOME ACIMA TODO NOME.\nAO NOME JESUS / TODO JOELHO SE DOBRAR / TODA LÍNGUA CONFESSAR: JESUS CRISTO É SENHOR / PARA GLÓRIA PAI.",
  "Fl 3,17–4,1": "IRMÃOS / IMITAR-ME / OLHAR QUEM VIVE SEGUNDO EXEMPLO.\nMUITOS VIVEM COMO INIMIGOS CRUZ / FIM DELES PERDIÇÃO / PENSAMENTO SÓ COISAS TERRENAS.\nNOSSA CIDADANIA ESTÁ NOS CÉUS / DE LÁ ESPERAMOS SALVADOR JESUS.\nELE TRANSFORMARÁ NOSSO CORPO FRÁGIL SEMELHANTE CORPO GLORIOSO.\nPORTANTO PERMANECER FIRMES NO SENHOR.",
  "Fl 3,8-14": "PAULO: CONSIDERO TUDO PERDA DIANTE VALOR CONHECER CRISTO JESUS.\nPERDI TUDO PARA GANHAR CRISTO / NÃO JUSTIÇA PRÓPRIA / MAS PELA FÉ.\nQUERO CONHECER CRISTO / PODER RESSURREIÇÃO / PARTICIPAR SOFRIMENTOS / CONFIGURAR-ME À MORTE / ALCANÇAR RESSURREIÇÃO.\nAINDA NÃO ALCANCEI / MAS CORRO / ESQUECER O QUE FICOU / AVANÇAR PARA META / PRÊMIO CHAMADO DEUS.",
  "Fl 4,12-14.19-20": "PAULO: SEI VIVER COM POUCO / SEI TER ABUNDÂNCIA / APRENDI SEGREDO EM TODA SITUAÇÃO / FOME OU FARTURA.\nTUDO POSSO NAQUELE QUE ME FORTALECE.\nVOCÊS FIZERAM BEM PARTICIPANDO MINHA TRIBULAÇÃO.\nMEU DEUS SUPRIRÁ TODA NECESSIDADE DE VOCÊS SEGUNDO RIQUEZA EM CRISTO.\nA DEUS PAI GLÓRIA.",
  "Fl 4,4-7": "ALEGREM-SE SEMPRE NO SENHOR / REPITO: ALEGREM-SE.\nBONDADE DE VOCÊS SER CONHECIDA / SENHOR ESTÁ PERTO.\nNÃO VIVER ANSIOSOS / EM TUDO APRESENTAR PEDIDOS A DEUS COM ORAÇÃO / SÚPLICA / AGRADECIMENTO.\nPAZ DE DEUS MAIOR QUE ENTENDIMENTO / GUARDAR CORAÇÕES E PENSAMENTOS EM CRISTO.",
  "Fl 4,6-9": "PREOCUPAÇÃO DOMINAR NÃO.\nEM TUDO / ORAÇÃO / PEDIDO / AGRADECIMENTO / APRESENTAR A DEUS.\nPAZ DEUS / MAIOR QUE ENTENDIMENTO / GUARDAR CORAÇÃO E PENSAMENTO EM CRISTO.\nPENSAR NO QUE É VERDADEIRO / DIGNO / JUSTO / PURO / AMÁVEL / BOM / VIRTUOSO.\nO QUE APRENDERAM / RECEBERAM / OUVIRAM / VIRAM / PRATICAR / DEUS PAZ COM VOCÊS.",

  "Fm 9-10.12-17": "PAULO, VELHO E PRISIONEIRO POR CRISTO / PEDIR POR ONÉSIMO / MEU FILHO GERADO NA PRISÃO.\nEU O ENVIO DE VOLTA / COMO MEU PRÓPRIO CORAÇÃO.\nQUERIA MANTER COMIGO / MAS NÃO SEM CONSENTIMENTO / PARA TEU BEM SER LIVRE / NÃO FORÇADO.\nTALVEZ ELE SE AFASTOU POR TEMPO PARA VOLTAR PARA SEMPRE / NÃO MAIS SÓ ESCRAVO / MAS IRMÃO AMADO.\nSE VOCÊ ME CONSIDERA COMPANHEIRO / RECEBE ELE COMO A MIM.",

  "Gl 1,1-2.6-10": "PAULO APÓSTOLO NÃO POR AUTORIDADE HUMANA / MAS JESUS CRISTO E DEUS PAI QUE O RESSUSCITOU.\nESTOU ADMIRADO VOCÊS TÃO RÁPIDO ABANDONAR GRAÇA PARA OUTRO EVANGELHO / NA VERDADE NÃO HÁ OUTRO.\nSE ALGUÉM ANUNCIAR EVANGELHO DIFERENTE / MESMO ANJO / NÃO ACEITAR.\nEU BUSCO AGRADAR HUMANOS OU DEUS? SE AINDA QUISESSE AGRADAR HUMANOS / NÃO SERIA SERVO CRISTO.",
  "Gl 1,11-19": "IRMÃOS / EVANGELHO QUE ANUNCIO NÃO É INVENÇÃO HUMANA / NÃO RECEBI NEM APRENDI DE HUMANO / MAS REVELAÇÃO JESUS CRISTO.\nVOCÊS SABEM COMO EU PERSEGUIA IGREJA / AVANÇAVA NO JUDAÍSMO.\nMAS DEUS ME SEPAROU DESDE VENTRE / CHAMOU PELA GRAÇA / REVELOU FILHO EM MIM PARA ANUNCIAR AOS GENTIOS.\nNÃO CONSULTEI LOGO HUMANOS / DEPOIS FUI JERUSALÉM CONHECER PEDRO E TIAGO.",
  "Gl 2,16.19-21": "SABEMOS PESSOA NÃO É JUSTIFICADA POR OBRAS LEI / MAS PELA FÉ EM JESUS CRISTO.\nEU PELA LEI MORRI PARA LEI / PARA VIVER PARA DEUS.\nFUI CRUCIFICADO COM CRISTO / JÁ NÃO SOU EU QUE VIVO / CRISTO VIVE EM MIM.\nVIDA AGORA / VIVO PELA FÉ NO FILHO DE DEUS / QUE ME AMOU E SE ENTREGOU POR MIM.\nNÃO ANULO GRAÇA DEUS.",
  "Gl 3,26-29": "TODOS VOCÊS PELA FÉ SÃO FILHOS DE DEUS EM CRISTO JESUS.\nQUANTOS FORAM BATIZADOS EM CRISTO / REVESTIRAM-SE DE CRISTO.\nNÃO HÁ JUDEU OU GREGO / ESCRAVO OU LIVRE / HOMEM E MULHER COMO DIVISÃO DE VALOR / TODOS UM EM CRISTO.\nSE VOCÊS DE CRISTO / SÃO DESCENDÊNCIA ABRAÃO / HERDEIROS PROMESSA.",
  "Gl 4,4-7": "QUANDO CHEGOU PLENITUDE TEMPO / DEUS ENVIOU FILHO / NASCIDO MULHER / NASCIDO SOB LEI / PARA RESGATAR QUEM ESTAVA SOB LEI / RECEBERMOS ADOÇÃO.\nPORQUE VOCÊS SÃO FILHOS / DEUS ENVIOU ESPÍRITO FILHO CORAÇÕES / CLAMAR: ABBA / PAI.\nVOCÊ NÃO É MAIS ESCRAVO / MAS FILHO / E SENDO FILHO / HERDEIRO POR DEUS.",
  "Gl 5,1.13-18": "PARA LIBERDADE CRISTO NOS LIBERTOU / PERMANECER FIRMES / NÃO VOLTAR JUGO ESCRAVIDÃO.\nVOCÊS CHAMADOS À LIBERDADE / NÃO USAR LIBERDADE PARA EGOÍSMO / MAS SERVIR UNS AOS OUTROS PELO AMOR.\nLEI SE CUMPRE: AMAR PRÓXIMO COMO A SI.\nCAMINHAR PELO ESPÍRITO / NÃO CEDER DESEJOS CARNE.\nESPÍRITO E CARNE SE OPÕEM / SE GUIADOS ESPÍRITO / NÃO SOB LEI.",
  "Gl 6,14-18": "LONGE DE MIM GLORIAR-ME EXCETO NA CRUZ SENHOR JESUS CRISTO / POR ELA MUNDO CRUCIFICADO PARA MIM / EU PARA MUNDO.\nCIRCUNCISÃO OU NÃO / O QUE IMPORTA É NOVA CRIAÇÃO.\nPAZ E MISERICÓRDIA SOBRE QUEM VIVE ESTA REGRA.\nNINGUÉM ME PERTURBE / EU CARREGO MARCAS JESUS NO CORPO.\nGRAÇA SENHOR COM VOCÊS.",

  "Hb 1,1-6": "MUITAS VEZES E MODOS / DEUS FALOU ANTIGAMENTE PELOS PROFETAS.\nAGORA NESTES ÚLTIMOS DIAS / FALOU PELO FILHO / HERDEIRO DE TUDO / POR QUEM CRIOU UNIVERSO.\nFILHO REFLEXO GLÓRIA DEUS / EXPRESSÃO SER DELE / SUSTENTA TUDO / PURIFICOU PECADOS / SENTOU DIREITA MAJESTADE.\nSUPERIOR AOS ANJOS / DEUS DIZ: TU ÉS MEU FILHO / ANJOS ADORAR.",
  "Hb 10,11-14.18": "TODO SACERDOTE ANTIGO FICAR DE PÉ DIA APÓS DIA / OFERECER MESMOS SACRIFÍCIOS QUE NÃO TIRAM PECADOS.\nCRISTO OFERECEU UM ÚNICO SACRIFÍCIO PELOS PECADOS / SENTOU DIREITA DEUS / ESPERAR INIMIGOS SOB PÉS.\nCOM UMA SÓ OFERTA / APERFEIÇOOU PARA SEMPRE OS SANTIFICADOS.\nONDE HÁ PERDÃO / NÃO PRECISA NOVA OFERTA PELO PECADO.",
  "Hb 10,5-10": "CRISTO AO ENTRAR MUNDO DIZ: SACRIFÍCIO E OFERTA NÃO QUERES / MAS CORPO PREPARASTE PARA MIM.\nEU VIM FAZER TUA VONTADE / COMO ESTÁ ESCRITO.\nELE TIRA PRIMEIRO SISTEMA PARA ESTABELECER SEGUNDO.\nPELA VONTADE DEUS / SOMOS SANTIFICADOS PELA OFERTA CORPO JESUS CRISTO UMA VEZ POR TODAS.",
  "Hb 11,1-2.8-19": "FÉ É FUNDAMENTO DO QUE ESPERAMOS / CERTEZA DO QUE NÃO VEMOS.\nPELA FÉ ABRAÃO OBEDECEU E PARTIU SEM SABER PARA ONDE / VIVEU COMO ESTRANGEIRO / ESPEROU CIDADE DEUS.\nPELA FÉ SARA RECEBEU FORÇA PARA GERAR / DE UM HOMEM QUASE MORTO VEIO DESCENDÊNCIA NUMEROSA.\nPELA FÉ ABRAÃO OFERECEU ISAAC / CONFIANDO DEUS PODE RESSUSCITAR MORTOS.",
  "Hb 11,8.11-12.17-19": "PELA FÉ ABRAÃO OBEDECEU CHAMADO / PARTIU PARA TERRA PROMETIDA SEM SABER DESTINO.\nPELA FÉ SARA RECEBEU CAPACIDADE GERAR / CONSIDEROU FIEL QUEM PROMETEU.\nDE UM HOMEM JÁ FRACO NASCEU DESCENDÊNCIA NUMEROSA.\nPELA FÉ ABRAÃO QUANDO PROVADO OFERECEU ISAAC / CONFIANDO DEUS PODERIA RESSUSCITAR.",
  "Hb 12,1-4": "CERCADOS POR NUVEM TESTEMUNHAS / DEIXAR TODO PESO E PECADO / CORRER COM PERSEVERANÇA CORRIDA PROPOSTA.\nOLHOS FIXOS JESUS / INICIADOR E CONSUMADOR FÉ / SUPORTOU CRUZ POR ALEGRIA À FRENTE / DESPREZOU VERGONHA / SENTOU DIREITA DEUS.\nCONSIDERAR ELE PARA NÃO DESANIMAR.\nNA LUTA CONTRA PECADO / VOCÊS AINDA NÃO RESISTIRAM ATÉ SANGUE.",
  "Hb 12,18-19.22-24": "VOCÊS NÃO CHEGARAM A MONTE MATERIAL COM FOGO / TREVAS / TEMPESTADE / VOZ TERRÍVEL.\nVOCÊS CHEGARAM MONTE SIÃO / CIDADE DEUS VIVO / JERUSALÉM CELESTE / MILHARES ANJOS / ASSEMBLEIA FESTIVA / IGREJA DOS PRIMOGÊNITOS / DEUS JUIZ / ESPÍRITOS JUSTOS / JESUS MEDIADOR NOVA ALIANÇA.",
  "Hb 12,5-7.11-13": "NÃO ESQUECER EXORTAÇÃO: FILHO / NÃO DESPREZAR CORREÇÃO SENHOR / NEM DESANIMAR QUANDO REPREENDIDO / SENHOR CORRIGE QUEM AMA.\nSUPORTAR DISCIPLINA COMO FILHOS.\nNO MOMENTO CORREÇÃO NÃO PARECE ALEGRE / DEPOIS PRODUZ FRUTO PAZ E JUSTIÇA.\nFORTALECER MÃOS CAÍDAS / JOELHOS FRACOS / FAZER CAMINHOS RETOS.",
  "Hb 2,9-11": "VEMOS JESUS / POR UM POUCO FEITO MENOR QUE ANJOS / AGORA COROADO GLÓRIA E HONRA POR TER SOFRIDO MORTE / PELA GRAÇA DEUS PROVAR MORTE POR TODOS.\nDEUS QUIS LEVAR MUITOS FILHOS À GLÓRIA / APERFEIÇOAR PELO SOFRIMENTO O AUTOR SALVAÇÃO.\nQUEM SANTIFICA E QUEM É SANTIFICADO / TODOS DE UMA ORIGEM / JESUS NÃO SE ENVERGONHA CHAMAR IRMÃOS.",
  "Hb 4,12-13": "PALAVRA DEUS VIVA / EFICAZ / MAIS AFIADA QUE ESPADA DOIS GUMES / PENETRA PROFUNDO / DISCERNE PENSAMENTOS E INTENÇÕES CORAÇÃO.\nNENHUMA CRIATURA ESCONDIDA DIANTE DEUS / TUDO NU E DESCOBERTO AOS OLHOS DAQUELE A QUEM PRESTAREMOS CONTAS.",
  "Hb 4,14-16": "TEMOS GRANDE SUMO SACERDOTE QUE ATRAVESSOU CÉUS / JESUS FILHO DEUS / MANTER FIRME CONFISSÃO.\nELE NÃO É INCAPAZ DE COMPADECER FRAQUEZAS / FOI TENTADO EM TUDO COMO NÓS / SEM PECAR.\nAPROXIMAR CONFIANTES DO TRONO GRAÇA / RECEBER MISERICÓRDIA E AJUDA NO TEMPO CERTO.",
  "Hb 5,1-6": "TODO SUMO SACERDOTE ESCOLHIDO ENTRE HUMANOS / REPRESENTA HUMANOS DIANTE DEUS / OFERECER DONS E SACRIFÍCIOS / COMPADECER IGNORANTES PORQUE TAMBÉM FRACO.\nNINGUÉM TOMA HONRA PARA SI / É CHAMADO POR DEUS COMO AARÃO.\nCRISTO TAMBÉM NÃO SE GLORIFICOU / DEUS DISSE: TU ÉS MEU FILHO / E: TU ÉS SACERDOTE PARA SEMPRE SEGUNDO MELQUISEDEC.",
  "Hb 5,7-9": "NOS DIAS CARNE / CRISTO OFERECEU ORAÇÕES E SÚPLICAS COM FORTE CLAMOR E LÁGRIMAS ÀQUELE QUE PODIA SALVÁ-LO MORTE / FOI OUVIDO POR SUA ENTREGA.\nSENDO FILHO / APRENDEU OBEDIÊNCIA PELO SOFRIMENTO.\nLEVADO À PERFEIÇÃO / TORNOU-SE CAUSA SALVAÇÃO ETERNA PARA QUEM OBEDECE.",
  "Hb 7,23-28": "ANTIGOS SACERDOTES ERAM MUITOS / MORTE IMPEDIA CONTINUAR.\nJESUS PERMANECE PARA SEMPRE / SACERDÓCIO NÃO PASSA.\nPOR ISSO PODE SALVAR COMPLETAMENTE QUEM SE APROXIMA DE DEUS POR ELE / VIVE SEMPRE PARA INTERCEDER.\nERA NECESSÁRIO SUMO SACERDOTE SANTO / INOCENTE / SEM MANCHA / ELEVADO CÉUS.\nNÃO PRECISA OFERECER SACRIFÍCIOS DIÁRIOS / OFERECEU A SI MESMO UMA VEZ.",
  "Hb 9,24-28": "CRISTO NÃO ENTROU SANTUÁRIO FEITO POR MÃOS / MAS NO PRÓPRIO CÉU / APARECER DIANTE DEUS POR NÓS.\nNÃO PRECISA OFERECER-SE MUITAS VEZES / SENÃO TERIA SOFRIDO REPETIDAMENTE.\nAGORA SE MANIFESTOU UMA VEZ / TIRAR PECADO PELO SACRIFÍCIO DE SI.\nHUMANOS MORREM UMA VEZ / DEPOIS JULGAMENTO.\nCRISTO OFERECIDO UMA VEZ PARA TIRAR PECADOS / APARECERÁ SEGUNDA VEZ PARA SALVAR QUEM O ESPERA.",

  "Rm 1,1-7": "PAULO SERVO JESUS CRISTO / CHAMADO APÓSTOLO / SEPARADO PARA EVANGELHO DEUS PROMETIDO PROFETAS.\nEVANGELHO SOBRE FILHO / DESCENDENTE DAVI SEGUNDO CARNE / CONSTITUÍDO FILHO DEUS EM PODER PELA RESSURREIÇÃO.\nPOR ELE RECEBEMOS GRAÇA E MISSÃO PARA LEVAR TODAS NAÇÕES À OBEDIÊNCIA FÉ.\nA TODOS AMADOS DEUS E CHAMADOS SANTOS / GRAÇA E PAZ.",
  "Rm 10,8-13": "PALAVRA ESTÁ PERTO / BOCA E CORAÇÃO / PALAVRA FÉ QUE ANUNCIAMOS.\nSE CONFESSAR BOCA JESUS É SENHOR / CRER CORAÇÃO DEUS RESSUSCITOU / SERÁ SALVO.\nCORAÇÃO CRÊ PARA JUSTIÇA / BOCA CONFESSA PARA SALVAÇÃO.\nNÃO HÁ DIFERENÇA JUDEU E GREGO / MESMO SENHOR RICO PARA TODOS QUE INVOCAM.\nTODO QUE INVOCAR NOME SENHOR SERÁ SALVO.",
  "Rm 11,13-15.29-32": "PAULO FALA A GENTIOS / HONRA MINISTÉRIO / ESPERA DESPERTAR CIÚME SANTO EM SEU POVO E SALVAR ALGUNS.\nSE REJEIÇÃO DELES TROUXE RECONCILIAÇÃO MUNDO / ACOLHIMENTO SERÁ VIDA DOS MORTOS.\nDONS E CHAMADO DEUS SÃO IRREVOGÁVEIS.\nTODOS FORAM ENVOLVIDOS DESOBEDIÊNCIA / PARA DEUS TER MISERICÓRDIA DE TODOS.",
  "Rm 11,33-36": "Ó PROFUNDIDADE RIQUEZA / SABEDORIA / CONHECIMENTO DEUS.\nJULGAMENTOS INSONDÁVEIS / CAMINHOS INCOMPREENSÍVEIS.\nQUEM CONHECEU MENTE SENHOR? QUEM FOI CONSELHEIRO? QUEM DEU PRIMEIRO PARA RECEBER DE VOLTA?\nDELE / POR ELE / PARA ELE SÃO TODAS COISAS.\nA ELE GLÓRIA PARA SEMPRE.",
  "Rm 12,1-2": "IRMÃOS / PELAS MISERICÓRDIAS DEUS / OFERECER CORPOS COMO SACRIFÍCIO VIVO / SANTO / AGRADÁVEL / ESTE CULTO VERDADEIRO.\nNÃO SE CONFORMAR COM ESTE MUNDO / TRANSFORMAR PELA RENOVAÇÃO MENTE / DISCERNIR VONTADE DEUS / BOA / AGRADÁVEL / PERFEITA.",
  "Rm 13,11-14": "VOCÊS SABEM O MOMENTO / HORA DE ACORDAR DO SONO / SALVAÇÃO MAIS PERTO.\nNOITE AVANÇOU / DIA APROXIMA.\nDEIXAR OBRAS TREVAS / VESTIR ARMAS LUZ.\nVIVER DECENTEMENTE / NÃO EM EXCESSOS / IMORALIDADE / BRIGAS / CIÚMES.\nREVESTIR SENHOR JESUS CRISTO.",
  "Rm 13,8-10": "NÃO FICAR DEVENDO NADA A NINGUÉM / EXCETO AMOR MÚTUO.\nQUEM AMA PRÓXIMO / CUMPRIU LEI.\nMANDAMENTOS NÃO ADULTERAR / NÃO MATAR / NÃO ROUBAR / NÃO COBIÇAR / RESUMEM-SE: AMAR PRÓXIMO COMO A SI.\nAMOR NÃO FAZ MAL AO PRÓXIMO / AMOR É PLENITUDE LEI.",
  "Rm 14,7-9": "NINGUÉM DE NÓS VIVE PARA SI / NINGUÉM MORRE PARA SI.\nSE VIVEMOS / PARA SENHOR; SE MORREMOS / PARA SENHOR.\nVIVOS OU MORTOS / PERTENCEMOS SENHOR.\nCRISTO MORREU E VOLTOU À VIDA PARA SER SENHOR DOS MORTOS E VIVOS.",
  "Rm 15,4-9": "TUDO ESCRITO ANTES / PARA NOSSA INSTRUÇÃO / PELA PERSEVERANÇA E CONSOLAÇÃO ESCRITURAS TER ESPERANÇA.\nDEUS DAR HARMONIA ENTRE VOCÊS SEGUNDO CRISTO / JUNTOS GLORIFICAR PAI.\nACOLHER UNS AOS OUTROS COMO CRISTO ACOLHEU.\nCRISTO SERVIU CIRCUNCISOS PARA CONFIRMAR PROMESSAS / E GENTIOS GLORIFICAR DEUS PELA MISERICÓRDIA.",
  "Rm 16,25-27": "ÀQUELE QUE PODE FORTALECER VOCÊS SEGUNDO MEU EVANGELHO E PREGAÇÃO JESUS CRISTO / REVELAÇÃO MISTÉRIO GUARDADO POR SÉCULOS / AGORA MANIFESTADO PELAS ESCRITURAS PROFÉTICAS / PARA TODAS NAÇÕES CHEGAREM À OBEDIÊNCIA FÉ.\nAO DEUS ÚNICO E SÁBIO / GLÓRIA POR JESUS CRISTO.",
  "Rm 3,21-25.28": "AGORA JUSTIÇA DEUS MANIFESTADA SEM DEPENDER DA LEI / LEI E PROFETAS TESTEMUNHAM.\nJUSTIÇA DEUS PELA FÉ EM JESUS CRISTO PARA TODOS QUE CREEM / NÃO HÁ DIFERENÇA.\nTODOS PECARAM / CARECEM GLÓRIA / SÃO JUSTIFICADOS GRATUITAMENTE PELA GRAÇA / REDENÇÃO EM CRISTO / OFERECIDO COMO PROPICIAÇÃO PELO SANGUE.\nCONCLUÍMOS: PESSOA É JUSTIFICADA PELA FÉ / NÃO POR OBRAS LEI.",
  "Rm 4,18-25": "ABRAÃO CONTRA TODA ESPERANÇA / CREU COM ESPERANÇA / TORNAR-SE PAI MUITAS NAÇÕES.\nNÃO ENFRAQUECEU FÉ AO CONSIDERAR CORPO ENVELHECIDO E SARA ESTÉRIL.\nNÃO DUVIDOU PROMESSA / FORTALECEU FÉ / DEU GLÓRIA A DEUS / CONVENCIDO QUE DEUS PODIA CUMPRIR.\nISSO FOI CONTADO COMO JUSTIÇA / TAMBÉM PARA NÓS QUE CREMOS NAQUELE QUE RESSUSCITOU JESUS.",
  "Rm 5,1-2.5-8": "JUSTIFICADOS PELA FÉ / TEMOS PAZ COM DEUS POR JESUS / ACESSO À GRAÇA / ESPERANÇA GLÓRIA.\nESPERANÇA NÃO DECEPCIONA / AMOR DEUS FOI DERRAMADO CORAÇÕES PELO ESPÍRITO SANTO.\nQUANDO AINDA FRACOS / CRISTO MORREU PELOS ÍMPIOS.\nDEUS PROVA AMOR: QUANDO AINDA PECADORES / CRISTO MORREU POR NÓS.",
  "Rm 5,1-5": "JUSTIFICADOS PELA FÉ / PAZ COM DEUS POR JESUS.\nPOR ELE ACESSO À GRAÇA / NOS ALEGRAMOS NA ESPERANÇA GLÓRIA.\nTAMBÉM NAS TRIBULAÇÕES / TRIBULAÇÃO PRODUZ PERSEVERANÇA / PERSEVERANÇA CARÁTER PROVADO / CARÁTER ESPERANÇA.\nESPERANÇA NÃO DECEPCIONA / AMOR DEUS DERRAMADO PELO ESPÍRITO.",
  "Rm 5,12-15": "POR UM HOMEM PECADO ENTROU MUNDO / PELO PECADO MORTE / MORTE PASSOU A TODOS.\nPECADO EXISTIA ANTES LEI / MORTE REINOU DE ADÃO A MOISÉS.\nADÃO É FIGURA DAQUELE QUE VIRIA.\nMAS DOM NÃO É COMO QUEDA: SE PELA QUEDA DE UM MUITOS MORRERAM / MUITO MAIS GRAÇA DEUS E DOM POR JESUS TRANSBORDARAM.",
  "Rm 5,12-19": "POR UM HOMEM PECADO ENTROU / MORTE POR PECADO / TODOS ATINGIDOS.\nADÃO FIGURA CRISTO / MAS DOM SUPERA QUEDA.\nJULGAMENTO DE UMA TRANSGRESSÃO TROUXE CONDENAÇÃO / GRAÇA SOBRE MUITAS FALTAS TRAZ JUSTIFICAÇÃO.\nPELA DESOBEDIÊNCIA DE UM / MUITOS FEITOS PECADORES; PELA OBEDIÊNCIA DE UM / MUITOS SERÃO JUSTOS.\nONDE PECADO AUMENTOU / GRAÇA SUPERABUNDOU.",
  "Rm 5,6-11": "QUANDO AINDA FRACOS / NO TEMPO CERTO CRISTO MORREU PELOS ÍMPIOS.\nDIFICILMENTE ALGUÉM MORRER POR JUSTO / TALVEZ POR BOM.\nDEUS PROVA AMOR: CRISTO MORREU POR NÓS QUANDO ÉRAMOS PECADORES.\nAGORA JUSTIFICADOS PELO SANGUE / SEREMOS SALVOS.\nQUANDO INIMIGOS FOMOS RECONCILIADOS PELA MORTE FILHO / MUITO MAIS SALVOS PELA VIDA DELE / ALEGRAMOS EM DEUS.",
  "Rm 6,3-4.8-11": "TODOS BATIZADOS EM CRISTO JESUS / BATIZADOS NA MORTE DELE.\nPELO BATISMO FOMOS SEPULTADOS COM ELE NA MORTE / PARA COMO CRISTO RESSUSCITOU / NÓS CAMINHAR VIDA NOVA.\nSE MORREMOS COM CRISTO / CREMOS VIVEREMOS COM ELE.\nCRISTO RESSUSCITADO NÃO MORRE MAIS / MORTE NÃO DOMINA.\nCONSIDERAR-SE MORTOS PARA PECADO / VIVOS PARA DEUS EM CRISTO.",
  "Rm 8,14-17": "TODOS GUIADOS ESPÍRITO DEUS / SÃO FILHOS DE DEUS.\nVOCÊS NÃO RECEBERAM ESPÍRITO ESCRAVIDÃO PARA MEDO / MAS ESPÍRITO ADOÇÃO / CLAMAMOS ABBA PAI.\nESPÍRITO TESTEMUNHA COM NOSSO ESPÍRITO QUE SOMOS FILHOS.\nSE FILHOS / HERDEIROS DEUS / COERDEIROS CRISTO / SE SOFREMOS COM ELE / TAMBÉM GLORIFICADOS.",
  "Rm 8,18-23": "SOFRIMENTOS PRESENTES NÃO SE COMPARAR GLÓRIA FUTURA.\nCRIAÇÃO ESPERA ANSIOSA REVELAÇÃO FILHOS DEUS / SUJEITA À FRUSTRAÇÃO / ESPERANÇA LIBERTAÇÃO.\nTODA CRIAÇÃO GEME COMO DORES PARTO.\nNÓS TAMBÉM / TEMOS PRIMEIROS FRUTOS ESPÍRITO / GEMEMOS ESPERANDO ADOÇÃO PLENA / REDENÇÃO CORPO.",
  "Rm 8,26-27": "ESPÍRITO AJUDA NOSSA FRAQUEZA / NÃO SABEMOS ORAR COMO DEVEMOS.\nPRÓPRIO ESPÍRITO INTERCEDE POR NÓS COM GEMIDOS INEXPRIMÍVEIS.\nDEUS QUE SONDA CORAÇÕES CONHECE INTENÇÃO ESPÍRITO / ELE INTERCEDE PELOS SANTOS CONFORME VONTADE DEUS.",
  "Rm 8,28-30": "SABEMOS: TODAS COISAS COOPERAM PARA BEM DE QUEM AMA DEUS / CHAMADOS SEGUNDO PROPÓSITO.\nAOS QUE DEUS CONHECEU / DESTINOU SER CONFORMES IMAGEM FILHO / PARA ELE SER PRIMOGÊNITO ENTRE IRMÃOS.\nAOS DESTINADOS / CHAMOU; AOS CHAMADOS / JUSTIFICOU; AOS JUSTIFICADOS / GLORIFICOU.",
  "Rm 8,31-34": "SE DEUS POR NÓS / QUEM CONTRA NÓS?\nELE NÃO POUPou PRÓPRIO FILHO / ENTREGOU POR TODOS / COMO NÃO DARÁ TUDO COM ELE?\nQUEM ACUSAR ELEITOS DEUS? DEUS JUSTIFICA.\nQUEM CONDENAR? CRISTO MORREU / RESSUSCITOU / ESTÁ DIREITA DEUS / INTERCEDE POR NÓS.",
  "Rm 8,35.37-39": "QUEM SEPARAR NÓS DO AMOR CRISTO? TRIBULAÇÃO / ANGÚSTIA / PERSEGUIÇÃO / FOME / PERIGO / ESPADA?\nEM TUDO SOMOS MAIS QUE VENCEDORES POR AQUELE QUE NOS AMOU.\nNEM MORTE NEM VIDA / ANJOS / PODERES / PRESENTE / FUTURO / ALTURA / PROFUNDIDADE / NADA CRIADO PODE SEPARAR DO AMOR DEUS EM CRISTO.",
  "Rm 8,8-11": "QUEM VIVE SÓ SEGUNDO CARNE NÃO PODE AGRADAR DEUS.\nMAS VOCÊS NÃO ESTÃO NA CARNE / ESTÃO NO ESPÍRITO / SE ESPÍRITO DEUS HABITA EM VOCÊS.\nSE CRISTO ESTÁ EM VOCÊS / CORPO MORTO PELO PECADO / ESPÍRITO VIDA PELA JUSTIÇA.\nSE ESPÍRITO DAQUELE QUE RESSUSCITOU JESUS HABITA EM VOCÊS / ELE DARÁ VIDA AOS CORPOS MORTAIS.",
  "Rm 8,9.11-13": "VOCÊS NÃO VIVEM SEGUNDO CARNE / MAS ESPÍRITO / SE ESPÍRITO DEUS HABITA.\nQUEM NÃO TEM ESPÍRITO CRISTO / NÃO PERTENCE A ELE.\nSE ESPÍRITO DEUS QUE RESSUSCITOU JESUS HABITA / ELE DARÁ VIDA CORPOS.\nNÃO SOMOS DEVEDORES À CARNE / SE VIVER SEGUNDO CARNE / MORRER; SE PELO ESPÍRITO MORTIFICAR OBRAS CORPO / VIVER.",
  "Rm 9,1-5": "PAULO FALAR VERDADE EM CRISTO / GRANDE TRISTEZA E DOR POR SEUS IRMÃOS ISRAEL.\nDESEJARIA ATÉ SER SEPARADO DE CRISTO POR ELES.\nDELES A ADOÇÃO / GLÓRIA / ALIANÇAS / LEI / CULTO / PROMESSAS / PATRIARCAS.\nDELES SEGUNDO CARNE VEM CRISTO / ACIMA DE TUDO / DEUS BENDITO.",

  "Tg 1,17-18.21-22.27": "TODO DOM BOM VEM DO ALTO / PAI DAS LUZES / NELE NÃO HÁ MUDANÇA.\nELE NOS GEROU PELA PALAVRA VERDADE / PRIMEIROS FRUTOS CRIAÇÃO.\nREJEITAR IMPUREZA / ACOLHER COM MANSIDÃO PALAVRA PLANTADA / PODE SALVAR.\nSEJAM PRATICANTES PALAVRA / NÃO SÓ OUVINTES.\nRELIGIÃO PURA: CUIDAR ÓRFÃOS E VIÚVAS NA AFLIÇÃO / GUARDAR-SE DA CORRUPÇÃO MUNDO.",
  "Tg 2,1-5": "IRMÃOS / FÉ EM JESUS CRISTO GLORIOSO NÃO COM PARCIALIDADE.\nSE ENTRAR RICO BEM VESTIDO E POBRE ROUPA SIMPLES / NÃO DAR LUGAR HONRA AO RICO E HUMILHAR POBRE.\nISSO É JULGAR COM CRITÉRIOS MAUS.\nDEUS ESCOLHEU POBRES AOS OLHOS MUNDO PARA SER RICOS NA FÉ / HERDEIROS REINO PROMETIDO A QUEM AMA.",
  "Tg 2,14-18": "QUE ADIANTA DIZER TENHO FÉ / MAS NÃO TER OBRAS? ESSA FÉ PODE SALVAR?\nSE IRMÃO SEM ROUPA E COMIDA / VOCÊ DIZ VAI EM PAZ MAS NÃO DÁ NECESSÁRIO / QUE ADIANTA?\nFÉ SEM OBRAS / MORTA.\nALGUÉM DIZ: VOCÊ TEM FÉ / EU OBRAS.\nMOSTRA FÉ SEM OBRAS / EU MOSTRO FÉ PELAS OBRAS.",
  "Tg 3,16–4,3": "ONDE INVEJA E AMBIÇÃO / DESORDEM E TODA MALDADE.\nSABEDORIA DO ALTO / PURA / PACÍFICA / AMÁVEL / MISERICORDIOSA / IMPARCIAL / SEM HIPOCRISIA.\nFRUTO JUSTIÇA SEMEADO EM PAZ POR QUEM PROMOVE PAZ.\nDE ONDE GUERRAS ENTRE VOCÊS? DOS DESEJOS QUE LUTAM DENTRO.\nVOCÊS QUEREM E NÃO TÊM / BRIGAM.\nPEDEM E NÃO RECEBEM PORQUE PEDEM PARA GASTAR EM PRAZERES.",
  "Tg 5,1-6": "AGORA RICOS OPRESSORES / CHORAR POR MISÉRIAS QUE VÊM.\nRIQUEZA APODRECE / ROUPAS TRAÇA / OURO ENFERRUJA / TESTEMUNHAR CONTRA VOCÊS.\nSALÁRIO DOS TRABALHADORES RETIDO CLAMA / GRITOS CHEGAM SENHOR DOS EXÉRCITOS.\nVOCÊS VIVERAM LUXO / ENGORDARAM CORAÇÃO.\nCONDENARAM E MATARAM JUSTO / ELE NÃO RESISTIU.",
  "Tg 5,7-10": "IRMÃOS / PACIÊNCIA ATÉ VINDA SENHOR.\nAGRICULTOR ESPERA FRUTO PRECIOSO / PACIENTE ATÉ CHUVAS.\nVOCÊS TAMBÉM FIRMAR CORAÇÕES / VINDA SENHOR ESTÁ PRÓXIMA.\nNÃO RECLAMAR UNS DOS OUTROS / JUIZ À PORTA.\nTOMAR PROFETAS COMO EXEMPLO DE SOFRIMENTO E PACIÊNCIA.",

  "Tt 2,11-14": "GRAÇA DEUS SE MANIFESTOU / TRAZ SALVAÇÃO A TODOS / EDUCA NÓS A RENUNCIAR IMPIEDADE E DESEJOS MUNDANOS / VIVER SÓBRIOS / JUSTOS / PIEDOSOS.\nESPERAR FELIZ ESPERANÇA / MANIFESTAÇÃO GLÓRIA JESUS CRISTO.\nELE SE ENTREGOU POR NÓS / RESGATAR TODO MAL / PURIFICAR POVO SEU / ZELOSO BOAS OBRAS.",
  "Tt 3,4-7": "QUANDO BONDADE E AMOR DE DEUS SALVADOR SE MANIFESTARAM / ELE NOS SALVOU / NÃO POR OBRAS JUSTAS NOSSAS / MAS MISERICÓRDIA.\nPELO BANHO RENASCIMENTO E RENOVAÇÃO ESPÍRITO SANTO / DERRAMADO SOBRE NÓS POR JESUS.\nJUSTIFICADOS PELA GRAÇA / TORNAR-SE HERDEIROS ESPERANÇA VIDA ETERNA."
});
